_SOURCES = json.loads('{"__init__":"\\"\\"\\"Truco Cu\\u00e1ntico: original hackathon implementation, October 2026.\\"\\"\\"\\n","i18n":"\\"\\"\\"English versions of engine messages. Spanish stays the canonical text in the code.\\"\\"\\"\\nERRORS = {\\n    \'Carta inv\\u00e1lida\': \'Invalid card\',\\n    \'Seleccion\\u00e1 un simulador IonQ; este backend no est\\u00e1 identificado como IonQ\': \'Select an IonQ simulator; this backend is not identified as IonQ\',\\n    \'Segu\\u00ed la indicaci\\u00f3n de Bot Q para continuar.\': \'Follow Bot Q\\u2019s instruction to continue.\',\\n    \'Resultado sin probabilidades v\\u00e1lidas\': \'Result without valid probabilities\',\\n    \'Resultado inv\\u00e1lido\': \'Invalid result\',\\n    \'Reparto inv\\u00e1lido: tres cartas por jugador\': \'Invalid deal: three cards per player\',\\n    \'Reparto inv\\u00e1lido: cartas repetidas\': \'Invalid deal: repeated cards\',\\n    \'Reparto inv\\u00e1lido: fichas\': \'Invalid deal: tokens\',\\n    \'Lecci\\u00f3n inv\\u00e1lida\': \'Invalid lesson\',\\n    \'Qollab permite un solo job IonQ por ejecuci\\u00f3n. No se inventar\\u00e1 una segunda medici\\u00f3n\': \'Qollab allows one IonQ job per run. A second measurement will not be invented\',\\n    \'Orden/formato de bits no reconocido: se esperaba un bit\': \'Unrecognised bit order/format: one bit was expected\',\\n    \'No se verific\\u00f3 que el backend sea simulador. No se enviar\\u00e1 a hardware\': \'The backend was not verified as a simulator. Nothing will be sent to hardware\',\\n    \'No hay medici\\u00f3n pendiente o lote incompleto\': \'No pending measurement, or incomplete batch\',\\n    \'No hay job remoto para consultar\': \'There is no remote job to query\',\\n    \'No hay circuitos para medir\': \'There are no circuits to measure\',\\n    \'Modo inv\\u00e1lido\': \'Invalid mode\',\\n    \'Modo cu\\u00e1ntico inv\\u00e1lido\': \'Invalid quantum mode\',\\n    \'Medici\\u00f3n inv\\u00e1lida\': \'Invalid measurement\',\\n    \'Mano inv\\u00e1lida\': \'Invalid mano\',\\n    \'La carta ya fue medida\': \'The card was already measured\',\\n    \'La carta no est\\u00e1 disponible para medir\': \'The card is not available to measure\',\\n    \'Inici\\u00e1 una partida\': \'Start a game\',\\n    \'Ingres\\u00e1 dos nombres de hasta 30 caracteres\': \'Enter two names of up to 30 characters\',\\n    \'Hay una medici\\u00f3n pendiente. Completala o consult\\u00e1 su resultado antes de cambiar de partida o lecci\\u00f3n.\': \'A measurement is pending. Complete it or check its result before changing game or lesson.\',\\n    \'Falta necesita el marcador\': \'Falta needs the score\',\\n    \'Eleg\\u00ed una carta\': \'Choose a card\',\\n    \'Eleg\\u00ed exactamente una carta\': \'Choose exactly one card\',\\n    \'El servidor local solo admite modo de desarrollo\': \'The local server only supports development mode\',\\n    \'Distribuci\\u00f3n inv\\u00e1lida\': \'Invalid distribution\',\\n    \'Dificultad inv\\u00e1lida\': \'Invalid difficulty\',\\n    \'Consult\\u00e1 el resultado IonQ pendiente antes de cambiar el modo de medici\\u00f3n.\': \'Check the pending IonQ result before changing the measurement mode.\',\\n    \'Confirm\\u00e1 antes de medir\': \'Confirm before measuring\',\\n    \'Circuito inv\\u00e1lido: hasta tres compuertas\': \'Invalid circuit: up to three gates\',\\n    \'Circuito confirmado: no puede cambiar\': \'Circuit confirmed: it cannot change\',\\n    \'Carta no disponible\': \'Card not available\',\\n    \'Cada ficha se usa una vez; m\\u00e1ximo tres\': \'Each token can be used once; three at most\',\\n    \'Acci\\u00f3n inv\\u00e1lida para este estado\': \'Invalid action for this state\',\\n    \'Privacidad inv\\u00e1lida\': \'Invalid privacy setting\',\\n    \'IonQ sigue pendiente. Reintentar consulta retoma el mismo job\': \'IonQ is still pending. Retrying resumes the same job\',\\n    \'No se pudo validar el resultado IonQ; no se asign\\u00f3 una identidad\': \'The IonQ result could not be validated; no identity was assigned\',\\n    \'IonQ inform\\u00f3 error o cancelaci\\u00f3n; no hay resultado de juego\': \'IonQ reported an error or cancellation; there is no game result\',\\n    \'Guion del tutorial desincronizado\': \'Tutorial script out of sync\',\\n    \'El env\\u00edo anterior tiene estado incierto. No se enviar\\u00e1 otro job que pueda duplicar la medici\\u00f3n\': \'The previous submission has an uncertain state. No job that could duplicate the measurement will be sent\',\\n    \'Modo dif\\u00edcil: ya usaste tus 2 retiros de compuertas en esta mano\': \'Hard mode: you already used your 2 gate removals this hand\',\\n}\\nimport re\\nPATTERNS = (\\n    (r\'^En el tutorial, segu\\u00ed la indicaci\\u00f3n de Bot Q: (.*)$\', r\'In the tutorial, follow Bot Q\\u2019s instruction: \\\\1\'),\\n    (r\'^Fall\\u00f3 el env\\u00edo \\\\((.*)\\\\); estado remoto incierto\\\\. No se reenviar\\u00e1 autom\\u00e1ticamente$\', r\'Submission failed (\\\\1); remote state uncertain. It will not be resent automatically\'),\\n    (r\'^Fall\\u00f3 la operaci\\u00f3n \\\\((.*)\\\\)\\\\. No se gener\\u00f3 un resultado\\\\.$\', r\'The operation failed (\\\\1). No result was produced.\'),\\n)\\n\\n\\ndef error_text(message, lang):\\n    \\"\\"\\"Translate an engine error; unknown messages are returned unchanged.\\"\\"\\"\\n    if lang != \'en\': return message\\n    if message in ERRORS: return ERRORS[message]\\n    for spanish, english in PATTERNS:\\n        if re.match(spanish, message): return re.sub(spanish, english, message)\\n    return message\\n","gates":"\\"\\"\\"Fixed rotation catalogue shared by the deck and Qiskit circuit builder.\\"\\"\\"\\nimport math\\nANGLES = {\'pi/2\': math.pi/2, \'pi/6\': math.pi/6, \'-pi/6\': -math.pi/6,\\n          \'pi/3\': math.pi/3}\\nROTATIONS = {f\'{axis}:{name}\': (axis.lower(), angle)\\n             for axis in (\'RX\', \'RY\', \'RZ\') for name, angle in ANGLES.items()}\\nVALID = (\'H\', \'X\', \'Z\', *ROTATIONS)\\n# Token deck: H, Z, RX, RY and RZ are equally likely (8 tokens each; each rotation axis\\n# has 4 angles x 2 copies) and X is rare (1 token): about 20 % each and 2.4 % for X.\\nDECK = (\'H\',)*8 + (\'X\',) + (\'Z\',)*8 + tuple(ROTATIONS)*2\\n","classic":"\\"\\"\\"Pure rules for the specified two-player, no-Flor variant.\\"\\"\\"\\nfrom dataclasses import dataclass\\nfrom itertools import combinations\\nfrom .gates import DECK as GATES\\n\\nNUMBERS = (1, 2, 3, 4, 5, 6, 7, 10, 11, 12)\\nSUITS = (\'espada\', \'basto\', \'oro\', \'copa\')\\nLINK = {\'espada\': \'copa\', \'copa\': \'espada\', \'basto\': \'oro\', \'oro\': \'basto\'}\\n\\n@dataclass(frozen=True)\\nclass Card:\\n    number: int\\n    suit: str\\n    def __post_init__(self):\\n        if self.number not in NUMBERS or self.suit not in SUITS:\\n            raise ValueError(\'Carta inv\\u00e1lida\')\\n    def linked(self):\\n        return Card(self.number, LINK[self.suit])\\n    def data(self):\\n        return {\'number\': self.number, \'suit\': self.suit, \'label\': f\'{self.number} de {self.suit}\'}\\n\\nDECK = tuple(Card(n, s) for n in NUMBERS for s in SUITS)\\nPAIRS = tuple((Card(n, s), Card(n, s).linked()) for n in NUMBERS for s in (\'espada\', \'basto\'))\\nSPECIAL = {(1, \'espada\'): 14, (1, \'basto\'): 13, (7, \'espada\'): 12, (7, \'oro\'): 11}\\nRANK = {3: 10, 2: 9, 1: 8, 12: 7, 11: 6, 10: 5, 7: 4, 6: 3, 5: 2, 4: 1}\\n\\ndef strength(card):\\n    return SPECIAL.get((card.number, card.suit), RANK[card.number])\\n\\ndef deal(rng):\\n    cards = [rng.choice(pair) for pair in rng.sample(PAIRS, 6)]\\n    rng.shuffle(cards)\\n    return [cards[:3], cards[3:]]\\n\\ndef envido(cards):\\n    value = lambda c: c.number if c.number <= 7 else 0\\n    same = [20 + value(a) + value(b) for a, b in combinations(cards, 2) if a.suit == b.suit]\\n    return max(same) if same else max(map(value, cards))\\n\\ndef hand_winner(bazas, mano):\\n    \\"\\"\\"None means undecided. -1 marks a parda; players are 0 and 1.\\"\\"\\"\\n    if not bazas:\\n        return None\\n    if len(bazas) >= 2:\\n        first, second = bazas[:2]\\n        if first == -1 and second != -1:\\n            return second\\n        if first != -1 and (second == first or second == -1):\\n            return first\\n    if len(bazas) == 3:\\n        first, second, third = bazas\\n        if third != -1:\\n            return third\\n        return next((p for p in (first, second) if p != -1), mano)\\n    return None\\n\\nENVIDO_CHAINS = {\\n    (): (\'envido\', \'real\', \'falta\'),\\n    (\'envido\',): (\'envido\', \'real\', \'falta\'),\\n    (\'envido\', \'envido\'): (\'real\', \'falta\'),\\n    (\'real\',): (\'falta\',),\\n    (\'envido\', \'real\'): (\'falta\',),\\n    (\'envido\', \'envido\', \'real\'): (\'falta\',),\\n}\\n\\ndef envido_value(chain, scores=None, loser=None):\\n    if chain[-1] == \'falta\':\\n        if scores is None:\\n            raise ValueError(\'Falta necesita el marcador\')\\n        return 15 - max(scores)\\n    return sum({\'envido\': 2, \'real\': 3}[c] for c in chain)\\n\\ndef refusal_value(chain):\\n    return envido_value(chain[:-1]) if len(chain) > 1 else 1\\n\\n\\n\\nclass GateDeck:\\n    def __init__(self, rng):\\n        self.rng = rng\\n        self.draw_pile = list(GATES)\\n        self.discard = []\\n        rng.shuffle(self.draw_pile)\\n    def draw_hand(self):\\n        if len(self.draw_pile) < 8:\\n            self.draw_pile.extend(self.discard)\\n            self.discard.clear()\\n            self.rng.shuffle(self.draw_pile)\\n        return [[self.draw_pile.pop() for _ in range(4)] for _ in range(2)]\\n    def discard_hand(self, hands):\\n        self.discard.extend(g for hand in hands for g in hand)\\n","quantum":"\\"\\"\\"Qiskit previews and explicit measurement sources. No game scoring here.\\"\\"\\"\\nimport math\\nimport random\\nfrom dataclasses import dataclass, field\\nfrom qiskit import QuantumCircuit\\nfrom qiskit.quantum_info import Statevector, Operator\\nimport numpy as np\\n\\nfrom .gates import VALID, ROTATIONS\\n\\ndef circuit(gates, measured=False):\\n    if not isinstance(gates, (list, tuple)) or len(gates) > 3 or any(g not in VALID for g in gates):\\n        raise ValueError(\'Circuito inv\\u00e1lido: hasta tres compuertas\')\\n    qc = QuantumCircuit(1, 1) if measured else QuantumCircuit(1)\\n    for gate in gates:\\n        if gate == \'H\': qc.h(0)\\n        elif gate == \'X\': qc.x(0)\\n        elif gate == \'Z\': qc.z(0)\\n        else:\\n            axis, angle = ROTATIONS[gate]\\n            getattr(qc, axis)(angle, 0)\\n    if measured: qc.measure(0, 0)\\n    return qc\\n\\ndef preview(gates):\\n    steps = []\\n    for i in range(len(gates) + 1):\\n        state = Statevector.from_instruction(circuit(gates[:i]))\\n        a, b = state.data\\n        cross = a.conjugate() * b\\n        phase = None if abs(a) < 1e-12 or abs(b) < 1e-12 else float(math.atan2(cross.imag, cross.real))\\n        steps.append({\'gate\': gates[i-1] if i else \'|0\\u27e9\',\\n                      \'amplitudes\': [[float(z.real), float(z.imag)] for z in (a, b)],\\n                      \'probabilities\': [float(p) for p in state.probabilities()],\\n                      \'bloch\': [float(2 * cross.real), float(2 * cross.imag), float(abs(a)**2 - abs(b)**2)],\\n                      \'relative_phase\': phase})\\n    # Partial rotations for a physically consistent Bloch trajectory.\\n    # H is a pi rotation around (X+Z)/sqrt(2), equivalent up to global phase.\\n    trajectory = [steps[0][\'bloch\']]\\n    segments = []\\n    for i, gate in enumerate(gates):\\n        start = len(trajectory) - 1\\n        state = Statevector.from_instruction(circuit(gates[:i]))\\n        axis, angle = ROTATIONS.get(gate, (None, math.pi))\\n        for t in range(1, 25):\\n            theta = angle * t / 24\\n            partial = QuantumCircuit(1)\\n            if axis: getattr(partial, axis)(theta, 0)\\n            elif gate == \'X\': partial.rx(theta, 0)\\n            elif gate == \'Z\': partial.rz(theta, 0)\\n            else:\\n                h = np.array([[1,1],[1,-1]]) / math.sqrt(2)\\n                partial.unitary(Operator(math.cos(theta/2)*np.eye(2)-1j*math.sin(theta/2)*h), [0])\\n            a, b = state.evolve(partial).data\\n            cross = a.conjugate()*b\\n            trajectory.append([float(2*cross.real),float(2*cross.imag),float(abs(a)**2-abs(b)**2)])\\n        segments.append({\'gate\':gate, \'start\':start, \'end\':len(trajectory)-1})\\n    return {\'gates\': list(gates), \'steps\': steps, \'trajectory\':trajectory, \'segments\':segments, **steps[-1]}\\n\\n@dataclass\\nclass QuantumCard:\\n    index: int\\n    tokens: list\\n    sequence: list = field(default_factory=list)\\n    locked: bool = False\\n    result: int | None = None\\n    record: dict | None = None\\n    _preview: dict | None = field(default=None, repr=False)\\n    def edit(self, indices):\\n        if self.locked: raise ValueError(\'Circuito confirmado: no puede cambiar\')\\n        if not isinstance(indices, (list, tuple)) or len(indices) > 3 or any(type(i) is not int or not 0 <= i < len(self.tokens) for i in indices) or len(set(indices)) != len(indices):\\n            raise ValueError(\'Cada ficha se usa una vez; m\\u00e1ximo tres\')\\n        self.sequence = list(indices)\\n        self._preview = None\\n        return self.view()\\n    @property\\n    def gates(self):\\n        return [self.tokens[i] for i in self.sequence]\\n    def view(self):\\n        if self._preview is None: self._preview = preview(self.gates)\\n        return self._preview\\n    def collapse(self, bit, record):\\n        if not self.locked: raise ValueError(\'Confirm\\u00e1 antes de medir\')\\n        if self.result is not None: raise ValueError(\'La carta ya fue medida\')\\n        if type(bit) is not int or bit not in (0, 1): raise ValueError(\'Resultado inv\\u00e1lido\')\\n        self.result, self.record = bit, record\\n\\nclass LocalSampler:\\n    name = \'LOCAL DEVELOPMENT \\u2014 Qiskit Statevector; NO IonQ\'\\n    def sample(self, gates):\\n        state = Statevector.from_instruction(circuit(gates))\\n        bit = int(state.sample_memory(1)[0])\\n        return bit, {\'backend\': self.name, \'shots\': 1, \'gates\': list(gates), \'result\': bit,\\n                     \'method\': \'Qiskit Statevector.sample_memory(1)\'}\\n\\ndef effective_sample(distribution, rng=None):\\n    \\"\\"\\"One effective draw from validated one-qubit probabilities/counts.\\"\\"\\"\\n    weights = [0.0, 0.0]\\n    for key, value in distribution.items():\\n        key = str(key).replace(\' \', \'\')\\n        if key in (\'0\', \'0x0\'): bit = 0\\n        elif key in (\'1\', \'0x1\'): bit = 1\\n        else: raise ValueError(\'Orden/formato de bits no reconocido: se esperaba un bit\')\\n        value = float(value)\\n        if not math.isfinite(value) or value < 0: raise ValueError(\'Distribuci\\u00f3n inv\\u00e1lida\')\\n        weights[bit] += value\\n    total = sum(weights)\\n    if not total or not math.isfinite(total): raise ValueError(\'Resultado sin probabilidades v\\u00e1lidas\')\\n    return int((rng or random.SystemRandom()).random() >= weights[0] / total)\\n","remote":"\\"\\"\\"Adapter for Qollab\'s documented injected Qiskit backend.\\n\\nNo credentials, provider construction or undocumented network endpoints.\\nLifecycle is polled by the UI so it stays responsive. Never substitutes local data.\\n\\"\\"\\"\\nimport time\\nfrom qiskit.providers.jobstatus import JobStatus\\nfrom .quantum import circuit, effective_sample\\n\\nclass RemoteMeasurement:\\n    def __init__(self, backend, one_job=True):\\n        self.backend = backend\\n        self.one_job = one_job\\n        self.sent = False\\n        self.job = None\\n        self.gates = []\\n        self.cached = None\\n        self.started = None\\n        self.last_error = None\\n        self.submission_uncertain = False\\n    def info(self):\\n        name = getattr(self.backend,\'name\',\'unknown\')\\n        if callable(name): name = name()\\n        config = self.backend.configuration() if hasattr(self.backend,\'configuration\') else None\\n        simulator = getattr(config,\'simulator\',None) if config else None\\n        module = type(self.backend).__module__\\n        return {\'name\':str(name),\'module\':module,\'simulator\':simulator,\\n                \'noise_model\':str(getattr(getattr(self.backend,\'options\',None),\'noise_model\',None))}\\n    def start(self, sequences):\\n        if self.job is not None: return  # resumes the SAME job after timeout\\n        if self.submission_uncertain:\\n            raise RuntimeError(\'El env\\u00edo anterior tiene estado incierto. No se enviar\\u00e1 otro job que pueda duplicar la medici\\u00f3n\')\\n        info = self.info()\\n        if \'ionq\' not in (info[\'name\']+\' \'+info[\'module\']).lower():\\n            raise ValueError(\'Seleccion\\u00e1 un simulador IonQ; este backend no est\\u00e1 identificado como IonQ\')\\n        if info[\'simulator\'] is not True and \'simulator\' not in info[\'name\'].lower():\\n            raise ValueError(\'No se verific\\u00f3 que el backend sea simulador. No se enviar\\u00e1 a hardware\')\\n        if self.sent and self.one_job:\\n            raise ValueError(\'Qollab permite un solo job IonQ por ejecuci\\u00f3n. No se inventar\\u00e1 una segunda medici\\u00f3n\')\\n        if not sequences: raise ValueError(\'No hay circuitos para medir\')\\n        circuits = [circuit(g, measured=True) for g in sequences]\\n        self.gates = [list(g) for g in sequences]\\n        self.sent = True  # fail closed after uncertain submission; avoid duplicate jobs\\n        self.started = time.monotonic()\\n        try:\\n            self.job = self.backend.run(circuits if len(circuits)>1 else circuits[0], shots=1)\\n        except Exception as exc:\\n            self.submission_uncertain = True\\n            message = str(exc).lower()\\n            recognized = next((p for p in (\'only one\',\'one job\',\'xhr\',\'xmlhttprequest\',\'keyword\',\'connection\',\'not supported\',\'unexpected\') if p in message), \'unclassified\')\\n            self.last_error = {\'type\':type(exc).__name__,\'recognized\':recognized}\\n            raise RuntimeError(f\'Fall\\u00f3 el env\\u00edo ({type(exc).__name__}; {recognized}); estado remoto incierto. No se reenviar\\u00e1 autom\\u00e1ticamente\') from None\\n    def poll(self):\\n        if self.cached is not None: return {\'done\':True,\'measurements\':self.cached}\\n        if self.job is None: raise ValueError(\'No hay job remoto para consultar\')\\n        status = self.job.status()\\n        if status in (JobStatus.ERROR,JobStatus.CANCELLED):\\n            self.last_error = str(status)\\n            raise RuntimeError(\'IonQ inform\\u00f3 error o cancelaci\\u00f3n; no hay resultado de juego\')\\n        if status != JobStatus.DONE:\\n            if time.monotonic()-self.started>120:\\n                raise TimeoutError(\'IonQ sigue pendiente. Reintentar consulta retoma el mismo job\')\\n            return {\'done\':False,\'status\':str(status)}\\n        try:\\n            result = self.job.result()\\n            measurements = []\\n            for i, gates in enumerate(self.gates):\\n                # A single bit: only 0/1 or 0x0/0x1 allowed. No low-probability filtering.\\n                counts = result.get_counts(i)\\n                bit = effective_sample(counts)\\n                job_id = str(self.job.job_id()) if hasattr(self.job,\'job_id\') else None\\n                record = {\'backend\':self.info(),\'shots\':1,\'gates\':gates,\'result\':bit,\\n                          \'job_id\':job_id,\'distribution\':dict(counts),\\n                          \'method\':\'one effective sample from returned counts/probabilities\'}\\n                measurements.append((bit,record))\\n            self.cached = measurements\\n            return {\'done\':True,\'measurements\':measurements}\\n        except Exception as exc:\\n            self.last_error = type(exc).__name__\\n            raise RuntimeError(\'No se pudo validar el resultado IonQ; no se asign\\u00f3 una identidad\') from None\\n    def release(self):\\n        self.job = None; self.cached = None; self.started = None\\n","game":"\\"\\"\\"Interface-independent state machine. Private projections are explicit.\\"\\"\\"\\nimport random\\nfrom datetime import datetime, timezone\\nfrom .classic import Card, deal, strength, envido, hand_winner, ENVIDO_CHAINS, envido_value, refusal_value, GateDeck\\nfrom .quantum import QuantumCard\\nfrom .gates import VALID\\n\\n# None means unlimited gate removals.\\nDIFFICULTIES = {\'normal\': None, \'hard\': 2}\\nHARD_LIMIT = \'Modo dif\\u00edcil: ya usaste tus 2 retiros de compuertas en esta mano\'\\n\\nLABELS = {\'envido\':\'Envido\', \'real\':\'Real Envido\', \'falta\':\'Falta Envido\',\\n          \'truco\':\'Truco\', \'retruco\':\'Retruco\', \'vale4\':\'Vale Cuatro\',\\n          \'accept\':\'Quiero\', \'reject\':\'No quiero\', \'fold\':\'Irse al mazo\',\\n          \'reassert\':\'Reafirmar canto\', \'confirm\':\'Confirmar\',\\n          \'next\':\'Nueva mano\'}\\n# Calls are proper names of the game and keep their Spanish name in English.\\nLABELS_EN = {**LABELS, \'fold\':\'Irse al mazo (fold)\', \'reassert\':\'Repeat the call\', \'confirm\':\'Confirm\', \'next\':\'Next hand\'}\\n\\nclass Game:\\n    def __init__(self, names, rng=None, privacy=False, quantum=True, deals=None, mano=None, difficulty=\'normal\'):\\n        if not isinstance(names, (list, tuple)) or len(names) != 2 or any(not isinstance(n,str) or not n.strip() or len(n)>30 for n in names):\\n            raise ValueError(\'Ingres\\u00e1 dos nombres de hasta 30 caracteres\')\\n        self.names = [n.strip() for n in names]\\n        if type(privacy) is not bool: raise ValueError(\\"Privacidad inv\\u00e1lida\\")\\n        self.privacy = privacy\\n        # Hard mode limits how many times each player may remove gates in a hand.\\n        if difficulty not in DIFFICULTIES: raise ValueError(\'Dificultad inv\\u00e1lida\')\\n        self.difficulty = difficulty\\n        # quantum=False plays classic Truco: no preparation phase and no measurements.\\n        if type(quantum) is not bool: raise ValueError(\'Modo cu\\u00e1ntico inv\\u00e1lido\')\\n        self.quantum = self.default_quantum = quantum\\n        self.deals = [self.validate_deal(d) for d in deals or []]\\n        self.rng = rng or random.SystemRandom()\\n        self.scores = [0,0]\\n        self.mano = self.rng.randrange(2) if mano is None else mano\\n        if self.mano not in (0,1): raise ValueError(\'Mano inv\\u00e1lida\')\\n        self.gate_deck = GateDeck(self.rng)\\n        self.history = []\\n        self.hand_number = 0\\n        self.new_hand()\\n    def new_hand(self):\\n        self.hand_number += 1\\n        # Scripted deals (tutorial) are used first; afterwards the deal is random.\\n        scripted = self.deals.pop(0) if self.deals else None\\n        self.quantum = scripted[\'quantum\'] if scripted and scripted[\'quantum\'] is not None else self.default_quantum\\n        self.cards = scripted[\'cards\'] if scripted else deal(self.rng)\\n        if scripted and scripted[\'tokens\']: self.tokens = [list(t) for t in scripted[\'tokens\']]\\n        else: self.tokens = self.gate_deck.draw_hand() if self.quantum else [[],[]]\\n        self.q = [None, None]\\n        self.removals_left = [DIFFICULTIES[self.difficulty]]*2\\n        self.played = [set(), set()]\\n        self.table = []\\n        self.bazas = []\\n        self.events = []\\n        self.actor = self.mano\\n        self.turn = self.mano\\n        self.phase = \'prepare\' if self.quantum else \'play\'\\n        self.stake = 1\\n        self.truco_right = None\\n        self.pending = None\\n        self.suspended = None\\n        self.envido_done = False\\n        self.envido_result = None\\n        self.measure_context = None\\n        self.measure_requests = []\\n        self.last_public_measurement = None\\n        self.winner = None\\n        self.event(\'Reparto de mano\', mano=self.mano)\\n    @staticmethod\\n    def validate_deal(entry):\\n        \\"\\"\\"A scripted deal: two hands of three cards, or a dict with \'cards\',\\n        optional \'quantum\' (use the quantum card this hand) and \'tokens\' (4 gates each).\\"\\"\\"\\n        entry = entry if isinstance(entry, dict) else {\'cards\': entry}\\n        hands = entry.get(\'cards\')\\n        if not isinstance(hands,(list,tuple)) or len(hands) != 2 or any(not isinstance(h,(list,tuple)) or len(h) != 3 for h in hands):\\n            raise ValueError(\'Reparto inv\\u00e1lido: tres cartas por jugador\')\\n        cards = [[c if isinstance(c,Card) else Card(*c) for c in hand] for hand in hands]\\n        if len({c for hand in cards for c in hand}) != 6: raise ValueError(\'Reparto inv\\u00e1lido: cartas repetidas\')\\n        tokens = entry.get(\'tokens\')\\n        if tokens is not None and (len(tokens) != 2 or any(len(t) != 4 or any(g not in VALID for g in t) for t in tokens)):\\n            raise ValueError(\'Reparto inv\\u00e1lido: fichas\')\\n        return {\'cards\': cards, \'quantum\': entry.get(\'quantum\'), \'tokens\': tokens}\\n    def event(self, text, **data):\\n        self.events.append({\'text\':text, \'time\':datetime.now(timezone.utc).isoformat(), **data})\\n    def effective_card(self, player, index):\\n        card = self.cards[player][index]\\n        q = self.q[player]\\n        return card.linked() if q is not None and q.index == index and q.result == 1 else card\\n    def can_envido(self):\\n        return not self.envido_done and not self.bazas and self.stake == 1 and not self.played[self.actor]\\n    def legal(self):\\n        if self.phase == \'prepare\': return [\'choose\',\'edit\',\'confirm\']\\n        if self.phase == \'play\':\\n            result = [\'play\',\'fold\']\\n            if self.can_envido(): result += list(ENVIDO_CHAINS[()])\\n            if self.stake < 4 and (self.stake == 1 or self.truco_right == self.actor):\\n                result += [{1:\'truco\',2:\'retruco\',3:\'vale4\'}[self.stake]]\\n            return result\\n        if self.phase == \'respond\':\\n            result = [\'accept\',\'reject\']\\n            if self.pending[\'kind\'] == \'envido\':\\n                result += list(ENVIDO_CHAINS.get(tuple(self.pending[\'chain\']), ()))\\n            else:\\n                if self.pending[\'level\'] < 4:\\n                    result += [{2:\'retruco\',3:\'vale4\'}[self.pending[\'level\']]]\\n                if self.can_envido(): result += list(ENVIDO_CHAINS[()])\\n            return result\\n        if self.phase == \'reassert\': return [\'reassert\']\\n        if self.phase == \'hand_end\': return [\'next\']\\n        return []\\n    def dispatch(self, action, value=None):\\n        if action not in self.legal(): raise ValueError(\'Acci\\u00f3n inv\\u00e1lida para este estado\')\\n        p = self.actor\\n        if action == \'choose\':\\n            if type(value) is not int or not 0 <= value < 3: raise ValueError(\'Carta inv\\u00e1lida\')\\n            q = self.q[p]\\n            if q is not None and q.index == value: return\\n            # Changing card discards the gates already placed: that is a removal.\\n            if q is not None and q.sequence: self.use_removal(p)\\n            self.q[p] = QuantumCard(value, self.tokens[p])\\n        elif action == \'edit\':\\n            q = self.q[p]\\n            if q is None: raise ValueError(\'Eleg\\u00ed una carta\')\\n            removes = isinstance(value, (list, tuple)) and any(i not in value for i in q.sequence)\\n            if removes and self.removals_left[p] == 0: raise ValueError(HARD_LIMIT)\\n            q.edit(value)\\n            if removes: self.use_removal(p)\\n        elif action == \'confirm\':\\n            if self.q[p] is None: raise ValueError(\'Eleg\\u00ed exactamente una carta\')\\n            self.q[p].locked = True\\n            other = 1-p\\n            if self.q[other] is None or not self.q[other].locked:\\n                self.actor = other\\n            else:\\n                self.phase = \'play\'; self.actor = self.turn = self.mano\\n        elif action in (\'envido\',\'real\',\'falta\'):\\n            if self.phase == \'respond\' and self.pending[\'kind\'] == \'envido\':\\n                chain = self.pending[\'chain\'] + [action]\\n            else:\\n                if self.phase == \'respond\': self.suspended = self.pending.copy()\\n                chain = [action]\\n            self.pending = {\'kind\':\'envido\',\'chain\':chain,\'proposer\':p}\\n            self.phase = \'respond\'; self.actor = 1-p\\n            self.event(\' \\u2192 \'.join(LABELS[c] for c in chain), player=p, kind=\'speech\', speech=action)\\n        elif action in (\'truco\',\'retruco\',\'vale4\'):\\n            level = {\'truco\':2, \'retruco\':3,\'vale4\':4}[action]\\n            # Raising a pending canto accepts its prior level implicitly.\\n            if self.phase == \'respond\': self.stake = self.pending[\'level\']\\n            self.pending = {\'kind\':\'truco\',\'level\':level,\'proposer\':p}\\n            self.phase = \'respond\'; self.actor = 1-p\\n            self.event(LABELS[action], player=p, kind=\'speech\', speech=action)\\n        elif action == \'reject\':\\n            self.event(\'No quiero\', player=p, kind=\'speech\', speech=\'reject\')\\n            pending = self.pending\\n            if pending[\'kind\'] == \'envido\':\\n                self.envido_done = True\\n                self.award(pending[\'proposer\'], refusal_value(pending[\'chain\']), \'Envido no querido\')\\n                self.pending = None\\n                if self.phase != \'match_end\': self.resume_truco()\\n            else:\\n                self.finish_hand(pending[\'proposer\'], pending[\'level\']-1, \'Truco no querido\')\\n        elif action == \'accept\':\\n            self.event(\'Quiero\', player=p, kind=\'speech\', speech=\'accept\')\\n            if self.pending[\'kind\'] == \'truco\':\\n                self.stake = self.pending[\'level\']; self.truco_right = p\\n                self.pending = None; self.phase = \'play\'; self.actor = self.turn\\n            else:\\n                self.envido_done = True\\n                self.envido_acceptor = p\\n                self.begin_measure(\'envido\', [self.mano,1-self.mano])\\n        elif action == \'reassert\':\\n            self.pending = self.suspended; self.suspended = None\\n            self.event(\'Truco reafirmado\', player=p, kind=\'speech\', speech=\'truco\')\\n            self.phase = \'respond\'; self.actor = 1-p\\n        elif action == \'play\':\\n            if type(value) is not int or not 0 <= value < 3 or value in self.played[p]:\\n                raise ValueError(\'Carta no disponible\')\\n            q = self.q[p]\\n            if q is not None and q.index == value and q.result is None:\\n                self.play_intent = (p, value)\\n                self.begin_measure(\'play\', [p])\\n            else: self.commit_play(p, value)\\n        elif action == \'fold\':\\n            self.event(\'Al mazo\', player=p, kind=\'speech\', speech=\'fold\')\\n            self.finish_hand(1-p, self.stake, \'Al mazo\')\\n        elif action == \'next\':\\n            self.mano = 1-self.mano\\n            self.new_hand()\\n    def use_removal(self, p):\\n        if self.removals_left[p] is None: return\\n        if self.removals_left[p] == 0: raise ValueError(HARD_LIMIT)\\n        self.removals_left[p] -= 1\\n    def begin_measure(self, context, players):\\n        self.measure_context = context\\n        self.measure_requests = [p for p in players if self.q[p] is not None and self.q[p].result is None]\\n        self.phase = \'measure\'\\n        if not self.measure_requests: self.after_measure()\\n    def complete_measure(self, measurements):\\n        if self.phase != \'measure\' or not isinstance(measurements, (list, tuple)) or len(measurements) != len(self.measure_requests):\\n            raise ValueError(\'No hay medici\\u00f3n pendiente o lote incompleto\')\\n        if any(not isinstance(item, (list, tuple)) or len(item) != 2 or\\n               type(item[0]) is not int or item[0] not in (0,1) or not isinstance(item[1], dict)\\n               for item in measurements):\\n            raise ValueError(\'Medici\\u00f3n inv\\u00e1lida\')\\n        # Validate the whole batch before collapsing any card.\\n        if any(not self.q[p].locked or self.q[p].result is not None for p in self.measure_requests):\\n            raise ValueError(\'La carta no est\\u00e1 disponible para medir\')\\n        for p, (bit, record) in zip(self.measure_requests, measurements):\\n            self.q[p].collapse(bit, {**record,\'moment\':self.measure_context})\\n        self.measure_requests = []\\n        self.after_measure()\\n    def after_measure(self):\\n        if self.measure_context == \'envido\':\\n            self.resolve_envido()\\n        else:\\n            p, index = self.play_intent\\n            self.last_public_measurement = {\'player\':p, **self.quantum_report(p)}\\n            public = {k:v for k,v in self.last_public_measurement.items() if k in (\'player\',\'original\',\'linked\',\'preview\',\'result\')}\\n            self.event(\'Carta medida\', kind=\'measurement\', measurement=public)\\n            self.commit_play(p, index)\\n    def resolve_envido(self):\\n        values = [envido([self.effective_card(p,i) for i in range(3)]) for p in (0,1)]\\n        winner = self.mano if values[0] == values[1] else int(values[1] > values[0])\\n        points = envido_value(self.pending[\'chain\'], self.scores, 1-winner)\\n        self.envido_result = {\'values\':values,\'winner\':winner,\'points\':points}\\n        first = self.envido_acceptor\\n        self.event(\'Tantos de Envido\', kind=\'speech\', speech=\'envido_first\', player=first, value=values[first])\\n        other = 1-first\\n        self.event(\'Respuesta de tantos\', kind=\'speech\', speech=\'envido_answer\', player=other, value=values[other], better=values[other]>values[first], tie=values[other]==values[first], mano=other==self.mano)\\n        self.award(winner, points, \'Envido querido\', values=values)\\n        self.pending = None\\n        if self.phase != \'match_end\': self.resume_truco()\\n    def resume_truco(self):\\n        if self.suspended:\\n            self.phase = \'reassert\'; self.actor = self.suspended[\'proposer\']\\n        else:\\n            self.phase = \'play\'; self.actor = self.turn\\n    def commit_play(self, p, index):\\n        card = self.effective_card(p,index)\\n        self.played[p].add(index)\\n        self.table.append({\'player\':p,\'card\':card.data()})\\n        self.event(\'Carta jugada\', player=p, card=card.data())\\n        if len(self.table) % 2:\\n            self.turn = self.actor = 1-p; self.phase = \'play\'; return\\n        pair = self.table[-2:]\\n        ranks = [strength(Card(item[\'card\'][\'number\'], item[\'card\'][\'suit\'])) for item in pair]\\n        winner = -1 if ranks[0] == ranks[1] else pair[int(ranks[1] > ranks[0])][\'player\']\\n        self.bazas.append(winner)\\n        self.event(\'Baza parda\' if winner == -1 else \'Baza ganada\', winner=winner,\\n                   cards=list(pair), strengths=ranks)\\n        outcome = hand_winner(self.bazas,self.mano)\\n        if outcome is not None: self.finish_hand(outcome,self.stake,\'Mano ganada\')\\n        else:\\n            self.turn = self.actor = pair[0][\'player\'] if winner == -1 else winner\\n            self.phase = \'play\'\\n    def award(self, player, points, reason, **data):\\n        before = self.scores[player]\\n        self.scores[player] = min(15,self.scores[player]+points)\\n        self.event(reason, winner=player, points=points, gained=self.scores[player]-before, **data)\\n        if self.scores[player] == 15:\\n            self.winner = player; self.phase = \'match_end\'\\n            self.archive()\\n    def finish_hand(self, winner, points, reason):\\n        self.award(winner,points,reason)\\n        if self.phase != \'match_end\':\\n            self.winner = winner; self.archive()\\n            self.phase = \'hand_end\'\\n    def archive(self):\\n        if self.history and self.history[-1][\'hand\'] == self.hand_number: return\\n        self.history.append({\'hand\':self.hand_number,\'mano\':self.mano,\'scores\':list(self.scores),\\n                             \'quantum\':[self.quantum_report(p) for p in (0,1)],\\n                             \'cards\':[[{\'original\':self.cards[p][i].data(), \'effective\':self.effective_card(p,i).data(),\\n                                        \'played\':i in self.played[p], \'quantum\':self.q[p] is not None and self.q[p].index==i}\\n                                       for i in range(3)] for p in (0,1)],\\n                             \'events\':list(self.events),\'bazas\':list(self.bazas)})\\n        self.gate_deck.discard_hand(self.tokens)\\n    def quantum_report(self,p):\\n        q = self.q[p]\\n        if q is None: return None\\n        original = self.cards[p][q.index]\\n        return {\'original\':original.data(), \'linked\':original.linked().data(),\\n                \'tokens\':list(q.tokens),\'sequence\':list(q.sequence), \'preview\':q.view(),\\n                \'result\':q.result,\'record\':q.record,\'locked\':q.locked,\\n                \'discarded\':[g for i,g in enumerate(q.tokens) if i not in q.sequence],\\n                \'explanation\': \'Termin\\u00f3 sin producir un resultado cl\\u00e1sico.\' if q.result is None else\\n                f\'La medici\\u00f3n produjo {q.result}. La identidad permanece fija durante la mano.\'}\\n    def public_view(self):\\n        data = {\'names\':self.names,\'scores\':self.scores,\'mano\':self.mano,\'actor\':self.actor,\\n                \'phase\':self.phase,\'hand\':self.hand_number,\'stake\':self.stake,\\n                \'bazas\':self.bazas,\'table\':self.table,\'pending\':self.pending,\\n                \'envido\':self.envido_result,\'events\':self.events,\\n                \'actions\':[{\'id\':a,\'label\':LABELS.get(a,a),\'label_en\':LABELS_EN.get(a,LABELS.get(a,a)),\\n                            \'hint\':self.action_hint(a),\'hint_en\':self.action_hint(a, en=True)}\\n                           for a in self.legal() if a not in (\'choose\',\'edit\',\'play\')],\\n                \'winner\':self.winner, \'privacy\':self.privacy, \'quantum\':self.quantum, \'difficulty\':self.difficulty}\\n        if self.last_public_measurement and self.phase != \'measure\':\\n            # The explicit public-play exception discloses circuit and preview, never tokens.\\n            data[\'public_measurement\'] = {k:v for k,v in self.last_public_measurement.items() if k in (\'player\',\'original\',\'linked\',\'preview\',\'result\',\'record\')}\\n        if self.phase == \'measure\' and self.measure_context == \'play\':\\n            p = self.play_intent[0]\\n            report = self.quantum_report(p)\\n            data[\'public_measurement\'] = {k:v for k,v in report.items() if k in (\'original\',\'linked\',\'preview\',\'result\')}\\n        if self.phase == \'match_end\': data[\'history\'] = self.history\\n        if self.phase in (\'hand_end\',\'match_end\'): data[\'report\'] = self.history[-1]\\n        return data\\n    def action_hint(self, action, en=False):\\n        \\"\\"\\"What each button does, in Spanish or English (game calls keep their names).\\"\\"\\"\\n        t = lambda es, english: english if en else es\\n        pts = lambda n: t(\'punto\' if n == 1 else \'puntos\', \'point\' if n == 1 else \'points\')\\n        if action == \'accept\':\\n            if self.pending[\'kind\'] == \'truco\':\\n                level = self.pending[\'level\']\\n                return t(f\\"La mano pasa a valer {level} puntos. Despu\\u00e9s se sigue jugando.\\", f\\"The hand becomes worth {level} points. Play continues.\\")\\n            chain = self.pending[\'chain\']\\n            stake = 15-max(self.scores) if chain[-1] == \'falta\' else envido_value(chain)\\n            measure = t(\' Se miden las cartas cu\\u00e1nticas que a\\u00fan no se midieron.\', \' Unmeasured quantum cards are measured.\') if self.quantum else \'\'\\n            return t(f\'El ganador suma {stake} puntos.\', f\'The winner scores {stake} points.\') + measure\\n        if action == \'reject\':\\n            pending = self.pending\\n            points = refusal_value(pending[\'chain\']) if pending[\'kind\'] == \'envido\' else pending[\'level\']-1\\n            ending = t(\'La mano contin\\u00faa.\', \'The hand continues.\') if pending[\'kind\'] == \'envido\' else t(\'La mano termina.\', \'The hand ends.\')\\n            if self.scores[pending[\'proposer\']] + points >= 15: ending = t(\'Llega a 15 y gana la partida.\', \'That reaches 15 and wins the match.\')\\n            name = self.names[pending[\'proposer\']]\\n            return t(f\\"{name} suma {points} {pts(points)}. {ending}\\", f\\"{name} scores {points} {pts(points)}. {ending}\\")\\n        if action == \'fold\':\\n            name = self.names[1-self.actor]\\n            return t(f\\"{name} suma {self.stake} {pts(self.stake)}. La mano termina.\\", f\\"{name} scores {self.stake} {pts(self.stake)}. The hand ends.\\")\\n        if action in (\'truco\',\'retruco\',\'vale4\'):\\n            points = {\'truco\':2,\'retruco\':3,\'vale4\':4}[action]\\n            return t(f\'Si el rival acepta, la mano vale {points} puntos; si rechaza, gan\\u00e1s {points-1}.\', f\'If accepted, the hand is worth {points} points; if declined, you win {points-1}.\')\\n        if action in (\'envido\',\'real\',\'falta\'):\\n            chain = self.pending[\'chain\'] + [action] if self.pending and self.pending[\'kind\'] == \'envido\' else [action]\\n            if action == \'falta\':\\n                need = 15-max(self.scores)\\n                return t(f\'Si acepta: {need} puntos, lo que le falta a quien va adelante para llegar a 15. Se define con los tantos.\', f\'If accepted: {need} points, what the leader still needs to reach 15. Decided by the envido count.\')\\n            return t(f\'Si acepta: {envido_value(chain)} puntos por los tantos, aparte de la mano.\', f\'If accepted: {envido_value(chain)} points for the envido count, separate from the hand.\')\\n        return {\'reassert\':t(\'El rival debe responder al Truco que qued\\u00f3 pendiente.\', \'Your opponent must answer the pending Truco.\'),\\n                \'next\':t(\'Se reparten tres cartas nuevas y cambia el jugador mano.\', \'Three new cards are dealt and the mano changes.\')}.get(action, \'\')\\n    def private_view(self):\\n        if self.phase not in (\'prepare\',\'play\',\'respond\',\'reassert\'): return {}\\n        p = self.actor\\n        data = {\'player\':p,\'quantum\':self.quantum_report(p)}\\n        if self.phase in (\'prepare\',\'play\',\'respond\',\'reassert\'):\\n            data[\'cards\'] = [{**self.effective_card(p,i).data(),\'index\':i,\'played\':i in self.played[p],\\n                              \'quantum\':self.q[p] is not None and self.q[p].index == i} for i in range(3)]\\n        if self.phase == \'prepare\':\\n            data[\'tokens\'] = self.tokens[p]\\n            data[\'removals_left\'] = self.removals_left[p]\\n        return data\\n","tutorial":"\\"\\"\\"Tutorials, in Spanish and English.\\n\\n1. Truco with Bot Q: one scripted match on the real engine. Hands 1-3 are classic\\n   Truco; hand 4 adds the quantum card. Each step is one of:\\n     - an explanation (\'title\'/\'text\'), advanced with \\u00abSiguiente\\u00bb;\\n     - an explanation with \'expect\': the only game action the player may take;\\n     - a \'bot\' move, executed automatically by the session;\\n     - a \'challenge\' or a \'quiz\' (hands 1-3 practise what the slides taught).\\n   \'target\' is a CSS selector the interface highlights. [X], [Y], [Z] are painted\\n   with the colour of that Bloch-sphere axis.\\n2. Gates and the Bloch sphere: lessons with Qiskit previews of each circuit.\\n\\nSources used for the explanations: the Argentine Truco rulebook published by\\nfolkloretradiciones.com.ar, IBM Quantum Learning (\\"Bits, gates and circuits\\") and\\nthe Quantum Education Modules page \\"Common quantum gates\\".\\n\\"\\"\\"\\n\\nNAMES = {\'es\': (\'Vos\', \'Bot Q\'), \'en\': (\'You\', \'Bot Q\')}\\nMANO = 0  # The player is mano in the first hand.\\n\\n# Fixed deals: [player cards, Bot Q cards]. Card indices in \'expect\' and \'bot\'\\n# refer to these positions.\\nDEALS = (\\n    # Hand 1 \\u00b7 reading the table, card strength, bazas.\\n    {\'cards\': (((3, \'espada\'), (5, \'copa\'), (12, \'basto\')),\\n               ((2, \'oro\'), (4, \'copa\'), (11, \'espada\')))},\\n    # Hand 2 \\u00b7 Bot Q is mano and calls Envido (player 33, Bot Q 30); parda.\\n    {\'cards\': (((7, \'oro\'), (6, \'oro\'), (4, \'basto\')),\\n               ((3, \'copa\'), (6, \'espada\'), (4, \'espada\')))},\\n    # Hand 3 \\u00b7 Truco and Retruco.\\n    {\'cards\': (((1, \'espada\'), (3, \'oro\'), (5, \'basto\')),\\n               ((1, \'basto\'), (12, \'oro\'), (10, \'copa\')))},\\n    # Hand 4 \\u00b7 the quantum card. X turns the weak 7 of cups into the 7 of swords.\\n    {\'cards\': (((7, \'copa\'), (4, \'oro\'), (5, \'basto\')),\\n               ((3, \'espada\'), (6, \'copa\'), (4, \'basto\'))),\\n     \'quantum\': True, \'tokens\': ((\'X\', \'H\', \'Z\', \'RY:pi/2\'), (\'H\', \'H\', \'Z\', \'Z\'))},\\n)\\n\\n# Hands 1-3 are a practice of what the slides taught. Besides the step types above:\\n#   - \'challenge\': every legal game action stays enabled; a wrong one is not played and\\n#     the player gets the hint for that action (\'hints\', keyed \'action:value\' or\\n#     \'action\'), or the step\'s default \'hint\'.\\n#   - \'quiz\': a question answered in Bot Q\'s panel; \'answer\' is the right option.\\n# \'ok\' is shown after a right answer.\\nCALL_HINT = (\'Ac\\u00e1 no hace falta cantar: el desaf\\u00edo es elegir la carta.\',\\n             \'No call is needed here: the challenge is choosing the card.\')\\nFOLD_HINT = (\'Irse al mazo le regala la mano al rival. Segu\\u00ed jugando.\',\\n             \'Going to the deck (fold) hands the hand to your opponent. Keep playing.\')\\nCALLS = {k: CALL_HINT for k in (\'envido\', \'real\', \'falta\', \'truco\', \'retruco\', \'vale4\')}\\n\\nSTEPS = (\\n    # ---------- Hand 1 \\u00b7 strength and bazas ----------\\n    {\'title\': \'Pr\\u00e1ctica con Bot Q\',\\n     \'text\': \'Ya viste las reglas; ahora las ponemos en pr\\u00e1ctica en cuatro manos: tres de Truco \'\\n             \'cl\\u00e1sico y una con la carta cu\\u00e1ntica. En los desaf\\u00edos eleg\\u00eds vos: si te equivoc\\u00e1s, la \'\\n             \'jugada no se hace y te doy una pista. El marcador est\\u00e1 arriba: gana el primero que \'\\n             \'llega a 15.\',\\n     \'title_en\': \'Practice with Bot Q\',\\n     \'text_en\': \'You have seen the rules; now let\\u2019s practise them over four hands: three of classic \'\\n                \'Truco and one with the quantum card. In the challenges you choose: if you get it \'\\n                \'wrong, the move is not played and I give you a hint. The scoreboard is at the top: \'\\n                \'the first to reach 15 wins.\',\\n     \'target\': \'.scoreboard\'},\\n    {\'title\': \'Desaf\\u00edo: gan\\u00e1 la primera baza\',\\n     \'text\': \'Sal\\u00eds vos. Ten\\u00e9s el 3 de espada, el 5 de copa y el 12 de basto. Abr\\u00ed con la carta que \'\\n             \'tiene m\\u00e1s chances de ganar.\',\\n     \'title_en\': \'Challenge: win the first baza\',\\n     \'text_en\': \'You lead. You hold the 3 of Swords, the 5 of Cups and the 12 of Clubs. Open with the \'\\n                \'card most likely to win.\',\\n     \'target\': \'.live-hand\', \'expect\': [\'play\', 0], \'challenge\': True,\\n     \'hint\': (\'Mir\\u00e1 la escala: \\u00bfcu\\u00e1l de tus tres cartas est\\u00e1 m\\u00e1s arriba?\',\\n              \'Check the ladder: which of your three cards is highest?\'),\\n     \'hints\': {**CALLS, \'fold\': FOLD_HINT,\\n               \'play:1\': (\'El 5 est\\u00e1 casi al fondo de la escala: solo le gana a los 4.\',\\n                          \'The 5 is near the bottom of the ladder: it only beats the 4s.\'),\\n               \'play:2\': (\'El 12 es bueno, pero los 3 est\\u00e1n m\\u00e1s arriba en la escala.\',\\n                          \'The 12 is decent, but the 3s are higher on the ladder.\')},\\n     \'ok\': (\'\\u00a1Bien! Los 3 est\\u00e1n justo debajo de las cuatro bravas.\',\\n            \'Well done! The 3s sit right below the four bravas.\')},\\n    {\'bot\': [\'play\', 0]},\\n    {\'title\': \'Ganaste la primera baza\',\\n     \'text\': \'Tu 3 le gan\\u00f3 a mi 2 de oro. Despu\\u00e9s de cada baza aparece un aviso: cerralo con \'\\n             \'\\u00abContinuar\\u00bb o eleg\\u00ed un tiempo autom\\u00e1tico con \\u23f1. Quien gana una baza sale primero en la \'\\n             \'siguiente.\',\\n     \'title_en\': \'You won the first baza\',\\n     \'text_en\': \'Your 3 beat my 2 of Coins. After each baza a notice appears: close it with \\u201cContinue\\u201d \'\\n                \'or choose an automatic time with \\u23f1. Whoever wins a baza leads the next one.\',\\n     \'target\': \'.played-bazas\'},\\n    {\'title\': \'Pregunta r\\u00e1pida\',\\n     \'text\': \'\\u00bfCu\\u00e1ntas bazas m\\u00e1s necesit\\u00e1s para ganar esta mano?\',\\n     \'title_en\': \'Quick question\',\\n     \'text_en\': \'How many more bazas do you need to win this hand?\',\\n     \'target\': \'.played-bazas\',\\n     \'quiz\': {\'options\': ((\'1\', \'1\'), (\'2\', \'2\'), (\'3\', \'3\')), \'answer\': 0},\\n     \'hint\': (\'La mano se gana con dos de las tres bazas, y ya ten\\u00e9s una.\',\\n              \'The hand is won with two of the three bazas, and you already have one.\'),\\n     \'ok\': (\'Una m\\u00e1s: con dos bazas la mano es tuya.\', \'One more: with two bazas the hand is yours.\')},\\n    {\'title\': \'Desaf\\u00edo: cerr\\u00e1 la mano\',\\n     \'text\': \'Te quedan el 5 de copa y el 12 de basto. Jug\\u00e1 la que tiene m\\u00e1s chances de ganar.\',\\n     \'title_en\': \'Challenge: close the hand\',\\n     \'text_en\': \'You have the 5 of Cups and the 12 of Clubs left. Play the one more likely to win.\',\\n     \'target\': \'.live-hand\', \'expect\': [\'play\', 2], \'challenge\': True,\\n     \'hint\': (\'Compar\\u00e1 las dos en la escala.\', \'Compare both on the ladder.\'),\\n     \'hints\': {**CALLS, \'fold\': FOLD_HINT,\\n               \'play:1\': (\'El 5 est\\u00e1 casi al fondo de la escala; el 12 est\\u00e1 bastante m\\u00e1s arriba.\',\\n                          \'The 5 is near the bottom of the ladder; the 12 is well above it.\')}},\\n    {\'bot\': [\'play\', 2]},\\n    {\'title\': \'Ganaste la mano\',\\n     \'text\': \'Tu 12 le gan\\u00f3 a mi 11: dos bazas, y como nadie cant\\u00f3, sum\\u00e1s 1 punto. Toc\\u00e1 \\u00abNueva \'\\n             \'mano\\u00bb: ahora soy mano yo.\',\\n     \'title_en\': \'You won the hand\',\\n     \'text_en\': \'Your 12 beat my 11: two bazas, and since nobody called, you score 1 point. Press \\u201cNext \'\\n                \'hand\\u201d: now I am mano.\',\\n     \'target\': \'[data-action=\\"next\\"]\', \'expect\': [\'next\', None]},\\n\\n    # ---------- Hand 2 \\u00b7 Envido and parda ----------\\n    {\'bot\': [\'envido\', None]},\\n    {\'title\': \'Te cant\\u00e9 Envido\',\\n     \'text\': \'Soy mano y cant\\u00e9 Envido antes de tirar. Antes de responder, cont\\u00e1 tus tantos: ten\\u00e9s \'\\n             \'7 de oro, 6 de oro y 4 de basto. \\u00bfCu\\u00e1ntos son?\',\\n     \'title_en\': \'I called Envido\',\\n     \'text_en\': \'I am mano and called Envido before playing. Before you answer, count your tantos: \'\\n                \'you hold the 7 of Coins, the 6 of Coins and the 4 of Clubs. How many are they?\',\\n     \'target\': \'.live-hand\',\\n     \'quiz\': {\'options\': ((\'13\', \'13\'), (\'17\', \'17\'), (\'33\', \'33\')), \'answer\': 2},\\n     \'hint\': (\'Ten\\u00e9s dos cartas de oro: sum\\u00e1 sus valores y agreg\\u00e1 20.\',\\n              \'You hold two Coins: add their values plus 20.\'),\\n     \'ok\': (\'\\u00a1Bien! 7 + 6 + 20 = 33, el m\\u00e1ximo posible.\', \'Right! 7 + 6 + 20 = 33, the highest possible.\')},\\n    {\'title\': \'Acept\\u00e1 el Envido\',\\n     \'text\': \'Con 33 no pod\\u00e9s perder. Podr\\u00edas subir con Envido, Real Envido o Falta Envido, pero \'\\n             \'esta vez toc\\u00e1 \\u00abQuiero\\u00bb: se comparan los tantos y el ganador suma 2.\',\\n     \'title_en\': \'Accept the Envido\',\\n     \'text_en\': \'With 33 you cannot lose. You could raise with Envido, Real Envido or Falta Envido, \'\\n                \'but this time press \\u201cQuiero\\u201d: the counts are compared and the winner scores 2.\',\\n     \'target\': \'[data-action=\\"accept\\"]\', \'expect\': [\'accept\', None]},\\n    {\'bot\': [\'play\', 0]},\\n    {\'title\': \'Ganaste el Envido\',\\n     \'text\': \'Tus 33 contra mis 30: sumaste 2. Los puntos del Envido van aparte y la mano sigue: ya \'\\n             \'tir\\u00e9 mi 3 de copa.\',\\n     \'title_en\': \'You won the Envido\',\\n     \'text_en\': \'Your 33 against my 30: you scored 2. Envido points are separate and the hand goes \'\\n                \'on: I have already played my 3 of Cups.\',\\n     \'target\': \'.scoreboard\'},\\n    {\'title\': \'Desaf\\u00edo: ganale a mi 3\',\\n     \'text\': \'Mi 3 de copa est\\u00e1 alto en la escala. Solo una de tus cartas le gana.\',\\n     \'title_en\': \'Challenge: beat my 3\',\\n     \'text_en\': \'My 3 of Cups is high on the ladder. Only one of your cards beats it.\',\\n     \'target\': \'.live-hand\', \'expect\': [\'play\', 0], \'challenge\': True,\\n     \'hint\': (\'Busc\\u00e1 una de las cuatro bravas.\', \'Look for one of the four bravas.\'),\\n     \'hints\': {**CALLS, \'fold\': FOLD_HINT,\\n               \'play:1\': (\'El 6 est\\u00e1 por debajo del 3: perder\\u00edas la baza.\',\\n                          \'The 6 is below the 3: you would lose the baza.\'),\\n               \'play:2\': (\'El 4 es de las cartas m\\u00e1s bajas del juego.\',\\n                          \'The 4 is among the lowest cards in the game.\')},\\n     \'ok\': (\'\\u00a1Eso! El 7 de oro es una brava.\', \'That\\u2019s it! The 7 of Coins is a brava.\')},\\n    {\'title\': \'Sal\\u00eds vos\',\\n     \'text\': \'Ganaste la baza, as\\u00ed que abr\\u00eds la segunda. Jug\\u00e1 tu 6 de oro.\',\\n     \'title_en\': \'You lead\',\\n     \'text_en\': \'You won the baza, so you lead the second one. Play your 6 of Coins.\',\\n     \'target\': \'[data-card=\\"1\\"]\', \'expect\': [\'play\', 1]},\\n    {\'bot\': [\'play\', 1]},\\n    {\'title\': \'Baza parda\',\\n     \'text\': \'Mi 6 de espada y tu 6 de oro tienen la misma fuerza: la segunda baza es parda. \'\\n             \'\\u00bfQui\\u00e9n gana la mano?\',\\n     \'title_en\': \'A parda (tied baza)\',\\n     \'text_en\': \'My 6 of Swords and your 6 of Coins have the same strength: the second baza is a \'\\n                \'parda. Who wins the hand?\',\\n     \'target\': \'.outcome\',\\n     \'quiz\': {\'options\': ((\'Yo, porque gan\\u00e9 la primera\', \'Me, because I won the first one\'),\\n                          (\'Bot Q, porque es mano\', \'Bot Q, because it is mano\'),\\n                          (\'Hay que jugar la tercera\', \'The third baza must be played\')),\\n              \'answer\': 0},\\n     \'hint\': (\'Si una baza es parda, decide la otra que ya tiene ganador.\',\\n              \'When a baza is a parda, the other baza that has a winner decides.\'),\\n     \'ok\': (\'Correcto: si la primera tiene ganador y la segunda es parda, gana quien gan\\u00f3 la primera.\',\\n            \'Correct: if the first baza has a winner and the second is a parda, the winner of the first takes the hand.\')},\\n    {\'title\': \'Otro punto\',\\n     \'text\': \'Ganaste la mano: 1 punto m\\u00e1s. Si las tres bazas fueran pardas, ganar\\u00eda el mano. Toc\\u00e1 \'\\n             \'\\u00abNueva mano\\u00bb.\',\\n     \'title_en\': \'Another point\',\\n     \'text_en\': \'You won the hand: 1 more point. If all three bazas were pardas, the mano would win. \'\\n                \'Press \\u201cNext hand\\u201d.\',\\n     \'target\': \'[data-action=\\"next\\"]\', \'expect\': [\'next\', None]},\\n\\n    # ---------- Hand 3 \\u00b7 Truco and Retruco ----------\\n    {\'title\': \'Desaf\\u00edo: es tu momento\',\\n     \'text\': \'Sos mano y ten\\u00e9s el ancho de espada, la mejor carta del juego, con el 3 de oro y el \'\\n             \'5 de basto. Hac\\u00e9 la apuesta que sube lo que vale la mano.\',\\n     \'title_en\': \'Challenge: your moment\',\\n     \'text_en\': \'You are mano and hold the ancho de espada, the best card in the game, with the 3 of \'\\n                \'Coins and the 5 of Clubs. Make the bet that raises what the hand is worth.\',\\n     \'target\': \'.live-hand\', \'expect\': [\'truco\', None], \'challenge\': True,\\n     \'hint\': (\'La apuesta sobre la mano es el Truco.\', \'The bet on the hand is the Truco.\'),\\n     \'hints\': {\'fold\': (\'\\u00bfIrte al mazo con el ancho de espada? Ten\\u00e9s la mejor carta del juego.\',\\n                        \'Fold with the ancho de espada? You hold the best card in the game.\'),\\n               \'play\': (\'Antes de tirar, aprovech\\u00e1 tu mano fuerte para apostar.\',\\n                        \'Before playing, use your strong hand to bet.\'),\\n               **{k: (\'Tus tantos son 5: no ten\\u00e9s dos cartas del mismo palo. Tu fuerza est\\u00e1 en las cartas, no en el Envido.\',\\n                      \'Your tantos are 5: no two cards share a suit. Your strength is in the cards, not the Envido.\')\\n                  for k in (\'envido\', \'real\', \'falta\')}}},\\n    {\'bot\': [\'accept\', None]},\\n    {\'title\': \'Dije \\u00abQuiero\\u00bb\',\\n     \'text\': \'Acept\\u00e9 el Truco: la mano vale 2. \\u00bfQui\\u00e9n puede cantar Retruco ahora?\',\\n     \'title_en\': \'I said \\u201cQuiero\\u201d\',\\n     \'text_en\': \'I accepted the Truco: the hand is worth 2. Who may call Retruco now?\',\\n     \'target\': \'.table-status\',\\n     \'quiz\': {\'options\': ((\'Yo, porque cant\\u00e9 Truco\', \'Me, because I called Truco\'),\\n                          (\'Bot Q, porque acept\\u00f3\', \'Bot Q, because it accepted\'),\\n                          (\'Cualquiera de los dos\', \'Either player\')),\\n              \'answer\': 1},\\n     \'hint\': (\'Solo puede subir la apuesta quien acaba de aceptar.\', \'Only the player who has just accepted may raise.\'),\\n     \'ok\': (\'Exacto: subir es derecho de quien acept\\u00f3. Y una vez aceptado el Truco, ya no se puede cantar Envido.\',\\n            \'Exactly: raising belongs to whoever accepted. And once Truco is accepted, Envido can no longer be called.\')},\\n    {\'title\': \'Desaf\\u00edo: guard\\u00e1 las fuertes\',\\n     \'text\': \'La mano vale 2. Abr\\u00ed sin gastar tus cartas fuertes: las vas a necesitar despu\\u00e9s.\',\\n     \'title_en\': \'Challenge: keep your strong cards\',\\n     \'text_en\': \'The hand is worth 2. Lead without spending your strong cards: you will need them later.\',\\n     \'target\': \'.live-hand\', \'expect\': [\'play\', 2], \'challenge\': True,\\n     \'hint\': (\'Abr\\u00ed con tu carta m\\u00e1s baja.\', \'Lead with your lowest card.\'),\\n     \'hints\': {**CALLS, \'fold\': FOLD_HINT,\\n               \'play:0\': (\'Es tu mejor carta: guardala para cuando la necesites.\',\\n                          \'It is your best card: keep it for when you need it.\'),\\n               \'play:1\': (\'El 3 es fuerte; abr\\u00ed con la m\\u00e1s baja.\', \'The 3 is strong; lead with the lowest.\')}},\\n    {\'bot\': [\'play\', 2]},\\n    {\'bot\': [\'retruco\', None]},\\n    {\'title\': \'Cant\\u00e9 Retruco\',\\n     \'text\': \'Mi 10 de copa le gan\\u00f3 a tu 5, y ahora cant\\u00e9 Retruco. Si dec\\u00eds \\u00abNo quiero\\u00bb, \\u00bfcu\\u00e1ntos \'\\n             \'puntos me llevo?\',\\n     \'title_en\': \'I called Retruco\',\\n     \'text_en\': \'My 10 of Cups beat your 5, and now I called Retruco. If you say \\u201cNo quiero\\u201d, how many \'\\n                \'points do I take?\',\\n     \'target\': \'.table-status\',\\n     \'quiz\': {\'options\': ((\'1\', \'1\'), (\'2\', \'2\'), (\'3\', \'3\')), \'answer\': 1},\\n     \'hint\': (\'Si rechaz\\u00e1s, me llevo lo que ya estaba aceptado: el Truco.\',\\n              \'If you decline, I take what was already accepted: the Truco.\'),\\n     \'ok\': (\'Exacto: 2, los del Truco aceptado.\', \'Exactly: 2, from the accepted Truco.\')},\\n    {\'title\': \'Acept\\u00e1 el Retruco\',\\n     \'text\': \'Te quedan el ancho de espada y el 3 de oro: toc\\u00e1 \\u00abQuiero\\u00bb y la mano pasa a valer 3.\',\\n     \'title_en\': \'Accept the Retruco\',\\n     \'text_en\': \'You still hold the ancho de espada and the 3 of Coins: press \\u201cQuiero\\u201d and the hand \'\\n                \'becomes worth 3.\',\\n     \'target\': \'[data-action=\\"accept\\"]\', \'expect\': [\'accept\', None]},\\n    {\'bot\': [\'play\', 0]},\\n    {\'title\': \'Desaf\\u00edo: ganale al ancho de basto\',\\n     \'text\': \'Tir\\u00e9 el ancho de basto, la segunda carta m\\u00e1s fuerte del juego. Solo una carta le gana.\',\\n     \'title_en\': \'Challenge: beat the ancho de basto\',\\n     \'text_en\': \'I played the ancho de basto, the second strongest card in the game. Only one card beats it.\',\\n     \'target\': \'.live-hand\', \'expect\': [\'play\', 0], \'challenge\': True,\\n     \'hint\': (\'Solo la carta n\\u00famero 1 de la escala le gana.\', \'Only the top card of the ladder beats it.\'),\\n     \'hints\': {**CALLS, \'fold\': FOLD_HINT,\\n               \'vale4\': (\'Podr\\u00edas subir a Vale Cuatro, pero primero gan\\u00e1 esta baza.\',\\n                         \'You could raise to Vale Cuatro, but win this baza first.\'),\\n               \'play:1\': (\'El 3 de oro est\\u00e1 muy por debajo del ancho de basto.\',\\n                          \'The 3 of Coins is far below the ancho de basto.\')}},\\n    {\'title\': \'\\u00daltima baza\',\\n     \'text\': \'Una baza cada uno: decide la tercera. Jug\\u00e1 tu 3 de oro.\',\\n     \'title_en\': \'Last baza\',\\n     \'text_en\': \'One baza each: the third one decides. Play your 3 of Coins.\',\\n     \'target\': \'[data-card=\\"1\\"]\', \'expect\': [\'play\', 1]},\\n    {\'bot\': [\'play\', 1]},\\n    {\'title\': \'Ganaste la mano\',\\n     \'text\': \'Tu 3 le gan\\u00f3 a mi 12. \\u00bfCu\\u00e1ntos puntos sumaste?\',\\n     \'title_en\': \'You won the hand\',\\n     \'text_en\': \'Your 3 beat my 12. How many points did you score?\',\\n     \'target\': \'.outcome\',\\n     \'quiz\': {\'options\': ((\'1\', \'1\'), (\'2\', \'2\'), (\'3\', \'3\')), \'answer\': 2},\\n     \'hint\': (\'La mano vale lo \\u00faltimo que se acept\\u00f3: el Retruco.\', \'The hand is worth the last accepted call: the Retruco.\'),\\n     \'ok\': (\'3 puntos: el Retruco aceptado.\', \'3 points: the accepted Retruco.\')},\\n    {\'title\': \'Ahora, la carta cu\\u00e1ntica\',\\n     \'text\': \'Ya practicaste el Truco cl\\u00e1sico. Toc\\u00e1 \\u00abNueva mano\\u00bb: llega la parte cu\\u00e1ntica, que te \'\\n             \'explico paso a paso.\',\\n     \'title_en\': \'Now, the quantum card\',\\n     \'text_en\': \'You have practised classic Truco. Press \\u201cNext hand\\u201d: the quantum part comes next, and \'\\n                \'I will explain it step by step.\',\\n     \'target\': \'[data-action=\\"next\\"]\', \'expect\': [\'next\', None]},\\n\\n    # ---------- Hand 4 \\u00b7 the quantum card ----------\\n    {\'bot\': [\'choose\', 0]},\\n    {\'bot\': [\'confirm\', None]},\\n    {\'title\': \'La carta cu\\u00e1ntica\',\\n     \'text\': \'Ahora jugamos con la carta cu\\u00e1ntica que viste en las diapositivas: eleg\\u00ed una carta, \'\\n             \'arm\\u00e1 su circuito y al jugarla se mide. Record\\u00e1 los palos ligados: basto \\u2194 oro y copa \\u2194 \'\\n             \'espada. Yo ya prepar\\u00e9 la m\\u00eda.\',\\n     \'title_en\': \'The quantum card\',\\n     \'text_en\': \'Now we play with the quantum card you saw in the slides: pick a card, build its circuit \'\\n                \'and it is measured when played. Remember the linked suits: clubs \\u2194 coins and cups \\u2194 \'\\n                \'swords. I have already prepared mine.\',\\n     \'target\': \'.live-hand\'},\\n    {\'title\': \'Eleg\\u00ed tu carta cu\\u00e1ntica\',\\n     \'text\': \'Tu 7 de copa es d\\u00e9bil (fuerza 4), pero su ligada es el 7 de espada, una brava (fuerza \'\\n             \'12). Tocalo para elegirlo como carta cu\\u00e1ntica.\',\\n     \'title_en\': \'Choose your quantum card\',\\n     \'text_en\': \'Your 7 of Cups is weak (strength 4), but its linked card is the 7 of Swords, a brava \'\\n                \'(strength 12). Tap it to make it your quantum card.\',\\n     \'target\': \'[data-card=\\"0\\"]\', \'expect\': [\'choose\', 0]},\\n    {\'title\': \'Agreg\\u00e1 la compuerta X\',\\n     \'text\': \'Toc\\u00e1 \\u00abActivar cu\\u00e1ntico\\u00bb para abrir el compositor y agreg\\u00e1 la ficha X. X da media vuelta \'\\n             \'alrededor del eje [X]: lleva la carta de la original a la ligada con 100 % de \'\\n             \'probabilidad.\',\\n     \'title_en\': \'Add the X gate\',\\n     \'text_en\': \'Press \\u201cActivate quantum\\u201d to open the composer and add the X token. X makes a half turn \'\\n                \'around the [X] axis: it moves the card from original to linked with 100% probability.\',\\n     \'target\': \'[data-token=\\"0\\"]\', \'expect\': [\'edit\', [0]]},\\n    {\'title\': \'Probabilidades y esfera\',\\n     \'text\': \'Arriba ves las dos identidades: ahora 0 % original y 100 % ligada. En la esfera de Bloch \'\\n             \'el norte es la original y el sur la ligada; la flecha baj\\u00f3 al sur girando alrededor del \'\\n             \'eje [X]. La altura sobre el eje [Z] da los porcentajes.\',\\n     \'title_en\': \'Probabilities and the sphere\',\\n     \'text_en\': \'At the top you see both identities: now 0% original and 100% linked. On the Bloch \'\\n                \'sphere north is the original and south the linked card; the arrow moved south by \'\\n                \'turning around the [X] axis. The height along the [Z] axis gives the percentages.\',\\n     \'target\': \'.quantum-options\'},\\n    {\'title\': \'Tus fichas\',\\n     \'text\': \'Cada mano recib\\u00eds cuatro fichas y pod\\u00e9s usar hasta tres, en el orden que quieras: el \'\\n             \'orden cambia el resultado. En el nivel Dif\\u00edcil solo pod\\u00e9s sacar compuertas dos veces por \'\\n             \'mano. El tutorial de compuertas explica qu\\u00e9 hace cada una.\',\\n     \'title_en\': \'Your tokens\',\\n     \'text_en\': \'Each hand you get four tokens and may use up to three, in any order: the order changes \'\\n                \'the result. On the Hard level you may remove gates only twice per hand. The gates \'\\n                \'tutorial explains what each one does.\',\\n     \'target\': \'.gate-rack\'},\\n    {\'title\': \'Confirm\\u00e1\',\\n     \'text\': \'Toc\\u00e1 \\u00abConfirmar\\u00bb. El circuito queda fijo durante toda la mano.\',\\n     \'title_en\': \'Confirm\',\\n     \'text_en\': \'Press \\u201cConfirm\\u201d. The circuit stays fixed for the whole hand.\',\\n     \'target\': \'#lock-circuit\', \'expect\': [\'confirm\', None]},\\n    {\'bot\': [\'play\', 0]},\\n    {\'title\': \'Se midi\\u00f3 mi carta\',\\n     \'text\': \'Jugu\\u00e9 mi carta cu\\u00e1ntica sin compuertas, as\\u00ed que al medirla sali\\u00f3 la original: el 3 de \'\\n             \'espada (fuerza 10). Una carta cu\\u00e1ntica se mide cuando se juega o cuando se acepta un \'\\n             \'Envido, y desde ese momento su identidad ya no cambia.\',\\n     \'title_en\': \'My card was measured\',\\n     \'text_en\': \'I played my quantum card with no gates, so measuring it gave the original: the 3 of \'\\n                \'Swords (strength 10). A quantum card is measured when it is played or when an Envido is \'\\n                \'accepted, and from then on its identity no longer changes.\',\\n     \'target\': \'.played-bazas\'},\\n    {\'title\': \'Jug\\u00e1 tu carta cu\\u00e1ntica\',\\n     \'text\': \'Jugala: al medirse, la X garantiza el 7 de espada.\',\\n     \'title_en\': \'Play your quantum card\',\\n     \'text_en\': \'Play it: when it is measured, the X guarantees the 7 of Swords.\',\\n     \'target\': \'[data-card=\\"0\\"]\', \'expect\': [\'play\', 0]},\\n    {\'title\': \'\\u00a1Sali\\u00f3 el 7 de espada!\',\\n     \'text\': \'Tu carta se midi\\u00f3 como 7 de espada (fuerza 12) y le gan\\u00f3 a mi 3. Con H en lugar de X \'\\n             \'habr\\u00eda sido 50 % y 50 %: esa es la apuesta cu\\u00e1ntica. Ahora jug\\u00e1 el 5 de basto.\',\\n     \'title_en\': \'It came out as the 7 of Swords!\',\\n     \'text_en\': \'Your card was measured as the 7 of Swords (strength 12) and beat my 3. With H instead \'\\n                \'of X it would have been 50% and 50%: that is the quantum bet. Now play the 5 of Clubs.\',\\n     \'target\': \'[data-card=\\"2\\"]\', \'expect\': [\'play\', 2]},\\n    {\'bot\': [\'play\', 1]},\\n    {\'bot\': [\'play\', 2]},\\n    {\'title\': \'Una baza cada uno\',\\n     \'text\': \'Mi 6 de copa gan\\u00f3 la segunda y ya tir\\u00e9 el 4 de basto. Jug\\u00e1 tu 4 de oro.\',\\n     \'title_en\': \'One baza each\',\\n     \'text_en\': \'My 6 of Cups won the second baza and I have already played the 4 of Clubs. Play your \'\\n                \'4 of Coins.\',\\n     \'target\': \'[data-card=\\"1\\"]\', \'expect\': [\'play\', 1]},\\n    {\'title\': \'\\u00a1Terminaste el tutorial de Truco!\',\\n     \'text\': \'Baza parda: como ganaste la primera, la mano es tuya. Ya sab\\u00e9s jugar al Truco y usar la \'\\n             \'carta cu\\u00e1ntica. Con \\u00abVer resumen\\u00bb repas\\u00e1s esta mano: cada baza y c\\u00f3mo se midieron las \'\\n             \'cartas cu\\u00e1nticas. Despu\\u00e9s segu\\u00ed con \\u00abCompuertas y esfera de Bloch\\u00bb para entender qu\\u00e9 \'\\n             \'hace cada ficha.\',\\n     \'title_en\': \'You finished the Truco tutorial!\',\\n     \'text_en\': \'A parda: since you won the first baza, the hand is yours. You can now play Truco and use \'\\n                \'the quantum card. \\u201cSee summary\\u201d goes over this hand: each baza and how the quantum cards \'\\n                \'were measured. Then continue with \\u201cGates and the Bloch sphere\\u201d to learn what each token \'\\n                \'does.\',\\n     \'target\': \'.outcome\', \'final\': True},\\n)\\n\\n# ---------- Gates and the Bloch sphere ----------\\n# Each lesson shows one or more circuits; the interface animates each path on a Bloch\\n# sphere. Percentages are computed by Qiskit at runtime, never typed by hand.\\nGATE_LESSONS = (\\n    {\'title\': \'La esfera de Bloch: el mapa de tu carta\',\\n     \'title_en\': \'The Bloch sphere: a map of your card\',\\n     \'text\': \'Un qubit se puede dibujar como una flecha dentro de una esfera. El polo norte es |0\\u27e9, tu \'\\n             \'carta original; el polo sur es |1\\u27e9, la carta ligada. La altura de la flecha sobre el eje \'\\n             \'[Z] decide las probabilidades al medir: P(original) = (1 + [Z]) / 2. En el ecuador \'\\n             \'la carta est\\u00e1 50 % y 50 %. Los ejes [X] e [Y] marcan hacia d\\u00f3nde apunta la flecha en el \'\\n             \'ecuador: eso es la \\u00abfase\\u00bb, que no cambia los porcentajes pero s\\u00ed lo que hagan las \'\\n             \'compuertas siguientes.\',\\n     \'text_en\': \'A qubit can be drawn as an arrow inside a sphere. The north pole is |0\\u27e9, your original \'\\n                \'card; the south pole is |1\\u27e9, the linked card. The arrow\\u2019s height along the [Z] axis \'\\n                \'sets the measurement odds: P(original) = (1 + [Z]) / 2. On the equator the card is \'\\n                \'50% and 50%. The [X] and [Y] axes say where the arrow points around the equator: that \'\\n                \'is the \\u201cphase\\u201d, which does not change the odds but does change what later gates do.\',\\n     \'analogy\': \'Pensalo como una br\\u00fajula de la carta: la latitud dice qu\\u00e9 tan probable es cada palo; \'\\n                \'la longitud es una marca invisible que solo se nota cuando otra compuerta la usa.\',\\n     \'analogy_en\': \'Think of it as the card\\u2019s compass: latitude tells how likely each suit is; longitude \'\\n                   \'is an invisible mark that only shows when another gate uses it.\',\\n     \'circuits\': (((), \'Sin compuertas: la flecha est\\u00e1 en el norte. 100 % original.\',\\n                   \'No gates: the arrow is at the north pole. 100% original.\'),\\n                  ((\'X\',), \'En el sur: 100 % ligada.\', \'At the south pole: 100% linked.\'),\\n                  ((\'H\',), \'En el ecuador: 50 % y 50 %.\', \'On the equator: 50% and 50%.\'))},\\n    {\'title\': \'X: cambiar de palo\',\\n     \'title_en\': \'X: switch the suit\',\\n     \'text\': \'X da media vuelta (180\\u00b0) alrededor del eje [X]. Intercambia los papeles de |0\\u27e9 y |1\\u27e9: \'\\n             \'desde la original lleva a la ligada con 100 %. Es el equivalente cu\\u00e1ntico del NOT de la \'\\n             \'computaci\\u00f3n cl\\u00e1sica. Dos X seguidas se cancelan.\',\\n     \'text_en\': \'X makes a half turn (180\\u00b0) around the [X] axis. It swaps the roles of |0\\u27e9 and |1\\u27e9: from \'\\n                \'the original it reaches the linked card with 100%. It is the quantum version of the \'\\n                \'classical NOT. Two X gates in a row cancel out.\',\\n     \'analogy\': \'Es dar vuelta la carta a su pareja: el 7 de copa pasa a ser el 7 de espada, seguro.\',\\n     \'analogy_en\': \'It is like flipping the card to its partner: the 7 of Cups becomes the 7 of Swords, \'\\n                   \'for sure.\',\\n     \'circuits\': (((\'X\',), \'X: del norte al sur. 100 % ligada.\', \'X: north to south. 100% linked.\'),\\n                  ((\'X\', \'X\'), \'X\\u00b7X: ida y vuelta. Vuelve a la original.\', \'X\\u00b7X: there and back. Back to the original.\'))},\\n    {\'title\': \'H: la superposici\\u00f3n\',\\n     \'title_en\': \'H: superposition\',\\n     \'text\': \'H (Hadamard) da media vuelta alrededor del eje diagonal entre [X] y [Z]. Desde el norte \'\\n             \'deja la flecha en el ecuador: 50 % original y 50 % ligada. No es una carta escondida: la \'\\n             \'identidad reci\\u00e9n existe al medir. Y no es como mezclar: dos H seguidas vuelven exactamente \'\\n             \'a la original, porque las amplitudes interfieren y se cancelan.\',\\n     \'text_en\': \'H (Hadamard) makes a half turn around the diagonal axis between [X] and [Z]. From the \'\\n                \'north it leaves the arrow on the equator: 50% original and 50% linked. It is not a \'\\n                \'hidden card: the identity only exists once measured. And it is not like shuffling: two \'\\n                \'H gates in a row return exactly to the original, because the amplitudes interfere and \'\\n                \'cancel.\',\\n     \'analogy\': \'Una H es como tirar la carta al aire: mientras gira no es ni una ni la otra. Pero si \'\\n                \'la \\u00abgir\\u00e1s\\u00bb dos veces con H, cae siempre igual que al principio.\',\\n     \'analogy_en\': \'An H is like tossing the card in the air: while spinning it is neither one nor the \'\\n                   \'other. But \\u201cspin\\u201d it twice with H and it always lands as it started.\',\\n     \'circuits\': (((\'H\',), \'H: al ecuador. 50 % / 50 %.\', \'H: to the equator. 50% / 50%.\'),\\n                  ((\'H\', \'H\'), \'H\\u00b7H: vuelve al norte. 100 % original (interferencia).\', \'H\\u00b7H: back to the north. 100% original (interference).\'))},\\n    {\'title\': \'Z: la marca invisible (fase)\',\\n     \'title_en\': \'Z: the invisible mark (phase)\',\\n     \'text\': \'Z da media vuelta alrededor del eje [Z]. Si la flecha est\\u00e1 en un polo, no se mueve: Z \'\\n             \'sola no cambia nada que se pueda medir. Si est\\u00e1 en el ecuador, la lleva al lado opuesto \'\\n             \'(de +[X] a \\u2212[X]): los porcentajes siguen 50/50, pero cambi\\u00f3 la fase. Una H posterior \'\\n             \'convierte esa diferencia en un resultado distinto: H\\u00b7Z\\u00b7H equivale a X.\',\\n     \'text_en\': \'Z makes a half turn around the [Z] axis. If the arrow is at a pole it does not move: Z \'\\n                \'alone changes nothing you can measure. On the equator it moves the arrow to the \'\\n                \'opposite side (from +[X] to \\u2212[X]): the odds stay 50/50, but the phase changed. A later \'\\n                \'H turns that difference into a different result: H\\u00b7Z\\u00b7H is the same as X.\',\\n     \'analogy\': \'Es una marca en el dorso de la carta: si la mir\\u00e1s de frente no la ves, pero cambia \'\\n                \'hacia d\\u00f3nde cae cuando la volv\\u00e9s a \\u00abgirar\\u00bb con H.\',\\n     \'analogy_en\': \'It is a mark on the back of the card: looking at the face you cannot see it, but it \'\\n                   \'changes how it lands when you \\u201cspin\\u201d it again with H.\',\\n     \'circuits\': (((\'Z\',), \'Z desde el norte: no se mueve. 100 % original.\', \'Z from the north: no movement. 100% original.\'),\\n                  ((\'H\', \'Z\'), \'H\\u00b7Z: sigue 50/50, pero ahora apunta a \\u2212[X].\', \'H\\u00b7Z: still 50/50, but it now points to \\u2212[X].\'),\\n                  ((\'H\', \'Z\', \'H\'), \'H\\u00b7Z\\u00b7H: la fase se vuelve resultado. 100 % ligada.\', \'H\\u00b7Z\\u00b7H: the phase becomes a result. 100% linked.\'))},\\n    {\'title\': \'RX: girar de a poco alrededor de X\',\\n     \'title_en\': \'RX: small turns around X\',\\n     \'text\': \'RX gira un \\u00e1ngulo fijo alrededor del eje [X]. En el juego hay 30\\u00b0, 60\\u00b0, 90\\u00b0 y \\u221230\\u00b0. Cuanto \'\\n             \'m\\u00e1s gira desde el norte, m\\u00e1s probabilidad pasa a la ligada: P(ligada) = sen\\u00b2(\\u03b8/2). Con \'\\n             \'180\\u00b0 ser\\u00eda una X completa.\',\\n     \'text_en\': \'RX turns a fixed angle around the [X] axis. The game has 30\\u00b0, 60\\u00b0, 90\\u00b0 and \\u221230\\u00b0. The \'\\n                \'more it turns from the north, the more probability moves to the linked card: P(linked) \'\\n                \'= sin\\u00b2(\\u03b8/2). At 180\\u00b0 it would be a full X.\',\\n     \'analogy\': \'Es empujar la carta hacia su pareja sin darla vuelta del todo: un empuj\\u00f3n chico, un \'\\n                \'cambio chico de probabilidad.\',\\n     \'analogy_en\': \'It is nudging the card towards its partner without flipping it completely: a small \'\\n                   \'nudge, a small change in the odds.\',\\n     \'circuits\': (((\'RX:pi/6\',), \'RX 30\\u00b0: un poco de ligada.\', \'RX 30\\u00b0: a little linked.\'),\\n                  ((\'RX:pi/3\',), \'RX 60\\u00b0: un cuarto ligada.\', \'RX 60\\u00b0: one quarter linked.\'),\\n                  ((\'RX:pi/2\',), \'RX 90\\u00b0: al ecuador, 50/50.\', \'RX 90\\u00b0: to the equator, 50/50.\'))},\\n    {\'title\': \'RY: girar alrededor de Y\',\\n     \'title_en\': \'RY: turns around Y\',\\n     \'text\': \'RY gira alrededor del eje [Y]. Desde el norte mueve la probabilidad igual que RX, pero la \'\\n             \'flecha llega a otro punto del ecuador. Por eso, despu\\u00e9s de una H, RY(30\\u00b0) y RY(\\u221230\\u00b0) dan \'\\n             \'resultados opuestos: el sentido del giro importa.\',\\n     \'text_en\': \'RY turns around the [Y] axis. From the north it moves probability just like RX, but the \'\\n                \'arrow reaches a different point on the equator. That is why, after an H, RY(30\\u00b0) and \'\\n                \'RY(\\u221230\\u00b0) give opposite results: the direction of the turn matters.\',\\n     \'analogy\': \'Si H deja la carta \\u00aben el aire\\u00bb, RY la inclina hacia uno u otro palo seg\\u00fan el sentido \'\\n                \'del giro.\',\\n     \'analogy_en\': \'If H leaves the card \\u201cin the air\\u201d, RY tilts it towards one suit or the other \'\\n                   \'depending on the direction of the turn.\',\\n     \'circuits\': (((\'RY:pi/2\',), \'RY 90\\u00b0: al ecuador, sobre +[X].\', \'RY 90\\u00b0: to the equator, on +[X].\'),\\n                  ((\'H\', \'RY:pi/6\'), \'H y RY 30\\u00b0: se inclina a la ligada.\', \'H then RY 30\\u00b0: tilts towards the linked card.\'),\\n                  ((\'H\', \'RY:-pi/6\'), \'H y RY \\u221230\\u00b0: se inclina a la original.\', \'H then RY \\u221230\\u00b0: tilts towards the original.\'))},\\n    {\'title\': \'RZ: girar la fase de a poco\',\\n     \'title_en\': \'RZ: small phase turns\',\\n     \'text\': \'RZ gira alrededor del eje [Z]. Como Z, no cambia los porcentajes de medir ahora: mueve la \'\\n             \'flecha por el ecuador (cambia la fase). Su efecto aparece cuando una H posterior \'\\n             \'transforma esa fase en probabilidad.\',\\n     \'text_en\': \'RZ turns around the [Z] axis. Like Z, it does not change today\\u2019s odds: it moves the \'\\n                \'arrow along the equator (it changes the phase). Its effect appears when a later H turns \'\\n                \'that phase into probability.\',\\n     \'analogy\': \'Es girar la marca invisible del dorso un cuarto de vuelta: no se ve hasta la pr\\u00f3xima H.\',\\n     \'analogy_en\': \'It is turning the invisible mark on the back a quarter turn: it does not show until \'\\n                   \'the next H.\',\\n     \'circuits\': (((\'RZ:pi/2\',), \'RZ 90\\u00b0 desde el norte: nada cambia.\', \'RZ 90\\u00b0 from the north: nothing changes.\'),\\n                  ((\'H\', \'RZ:pi/2\'), \'H y RZ 90\\u00b0: la flecha va de +[X] a +[Y].\', \'H then RZ 90\\u00b0: the arrow goes from +[X] to +[Y].\'),\\n                  ((\'H\', \'RZ:pi/2\', \'H\'), \'H\\u00b7RZ 90\\u00b0\\u00b7H: ahora la fase cambia el resultado frente a H\\u00b7H.\', \'H\\u00b7RZ 90\\u00b0\\u00b7H: now the phase changes the result compared with H\\u00b7H.\'))},\\n    {\'title\': \'Combinaciones clave\',\\n     \'title_en\': \'Key combinations\',\\n     \'text\': \'Las compuertas se aplican en orden, de izquierda a derecha, y cada una act\\u00faa sobre lo que \'\\n             \'dej\\u00f3 la anterior. Por eso el orden importa. Combinaciones para recordar: H\\u00b7H = nada \'\\n             \'(vuelve a la original); X\\u00b7X = nada; H\\u00b7Z\\u00b7H = X (100 % ligada); H\\u00b7X = H (X no mueve una \'\\n             \'flecha que ya est\\u00e1 sobre +[X]); RY(30\\u00b0)\\u00b7H y H\\u00b7RY(30\\u00b0) dan resultados opuestos.\',\\n     \'text_en\': \'Gates are applied in order, left to right, and each acts on what the previous one left. \'\\n                \'That is why order matters. Combinations to remember: H\\u00b7H = nothing (back to the \'\\n                \'original); X\\u00b7X = nothing; H\\u00b7Z\\u00b7H = X (100% linked); H\\u00b7X = H (X does not move an arrow \'\\n                \'already on +[X]); RY(30\\u00b0)\\u00b7H and H\\u00b7RY(30\\u00b0) give opposite results.\',\\n     \'analogy\': \'Como en el Truco, no alcanza con tener buenas cartas: importa en qu\\u00e9 orden las jug\\u00e1s.\',\\n     \'analogy_en\': \'As in Truco, good cards are not enough: the order you play them in matters.\',\\n     \'circuits\': (((\'H\', \'Z\', \'H\'), \'H\\u00b7Z\\u00b7H = X: 100 % ligada.\', \'H\\u00b7Z\\u00b7H = X: 100% linked.\'),\\n                  ((\'H\', \'X\'), \'H\\u00b7X: X no cambia nada ac\\u00e1.\', \'H\\u00b7X: X changes nothing here.\'),\\n                  ((\'RY:pi/6\', \'H\'), \'RY 30\\u00b0 y despu\\u00e9s H.\', \'RY 30\\u00b0 then H.\'),\\n                  ((\'H\', \'RY:pi/6\'), \'H y despu\\u00e9s RY 30\\u00b0: resultado opuesto.\', \'H then RY 30\\u00b0: the opposite result.\'))},\\n    {\'title\': \'La medici\\u00f3n\',\\n     \'title_en\': \'Measurement\',\\n     \'text\': \'Medir da una sola respuesta: original o ligada. Los porcentajes dicen con qu\\u00e9 frecuencia \'\\n             \'saldr\\u00eda cada una si repiti\\u00e9ramos el mismo circuito muchas veces; un 50 % no garantiza que \'\\n             \'salga una vez cada una. En el juego tu carta se mide una sola vez, al jugarla o al \'\\n             \'aceptar un Envido, y desde ah\\u00ed su identidad queda fija hasta el final de la mano.\',\\n     \'text_en\': \'Measuring gives a single answer: original or linked. The percentages say how often each \'\\n                \'would come out if we repeated the same circuit many times; 50% does not guarantee one \'\\n                \'of each. In the game your card is measured only once, when it is played or when an \'\\n                \'Envido is accepted, and from then on its identity is fixed until the end of the hand.\',\\n     \'analogy\': \'Es como dar vuelta la carta sobre la mesa: una vez que se ve el palo, ya no cambia.\',\\n     \'analogy_en\': \'It is like turning the card face up on the table: once the suit is shown, it stays.\',\\n     \'circuits\': (((\'H\',), \'Antes de medir: 50/50. Al medir, una sola carta.\', \'Before measuring: 50/50. Measuring gives one card.\'),\\n                  ((\'RX:pi/3\',), \'75/25: la ligada sale una de cada cuatro veces, en promedio.\', \'75/25: the linked card comes out one time in four, on average.\'))},\\n)\\n","service":"\\"\\"\\"Session API shared by local HTTP and Qollab Python imports.\\"\\"\\"\\nimport json\\nimport platform\\nimport qiskit\\nfrom .game import Game\\nfrom .quantum import LocalSampler, preview\\nfrom .remote import RemoteMeasurement\\nfrom . import tutorial\\nfrom .i18n import error_text\\n\\nclass Session:\\n    def __init__(self, local=False):\\n        self.local = local\\n        self.host_local = local\\n        self.game = None\\n        self.remote = None\\n        self.guided = False  # True while the scripted tutorial match is active.\\n        self.coach = 0  # Index of the current tutorial step.\\n        self.feedback = None  # Bot Q\'s answer to the last challenge or quiz.\\n        self.lesson = None  # Index of the open gates lesson, if any.\\n        self.error = None\\n        self.errors = []\\n        self.lang = \'es\'  # Language of engine messages; the interface sends it with each action.\\n    def output(self, private=False):\\n        result = {\'mode\':LocalSampler.name if self.local else \'Qollab \\u00b7 IonQ injected backend \\u00b7 one-job limit\',\\n                  \'development_mode\':self.local, \'host_local\':self.host_local,\\n                  \'versions\':{\'python\':platform.python_version(),\'qiskit\':qiskit.__version__},\\n                  \'error\':self.error,\'guided\':self.guided, \'remote_info\':self.remote.info() if self.remote else None,\\n                  \'remote_error\':self.remote.last_error if self.remote else None}\\n        if self.game:\\n            result[\'game\'] = self.game.public_view()\\n            if private: result[\'private\'] = self.game.private_view()\\n        if self.guided: result[\'coach\'] = self.coach_view()\\n        if self.lesson is not None: result[\'lesson\'] = self.lesson_view()\\n        return result\\n    def coach_view(self):\\n        explained = [i for i, s in enumerate(tutorial.STEPS) if \'bot\' not in s]\\n        step = tutorial.STEPS[self.coach]\\n        return {\'title\':step[\'title\'], \'text\':step[\'text\'], \'title_en\':step.get(\'title_en\', step[\'title\']),\\n                \'text_en\':step.get(\'text_en\', step[\'text\']), \'target\':step.get(\'target\'),\\n                \'expect\':step.get(\'expect\'), \'final\':step.get(\'final\', False),\\n                \'challenge\':step.get(\'challenge\', False),\\n                \'quiz\':{\'options\':[{\'es\':es, \'en\':en} for es, en in step[\'quiz\'][\'options\']],\\n                        \'answer\':step[\'quiz\'][\'answer\']} if \'quiz\' in step else None,\\n                \'feedback\':self.feedback,\\n                \'step\':explained.index(self.coach)+1, \'total\':len(explained)}\\n    def lesson_view(self):\\n        lesson = tutorial.GATE_LESSONS[self.lesson]\\n        return {**{k: v for k, v in lesson.items() if k != \'circuits\'}, \'index\': self.lesson,\\n                \'total\': len(tutorial.GATE_LESSONS),\\n                \'circuits\': [{\'preview\': preview(list(gates)), \'caption\': es, \'caption_en\': en}\\n                             for gates, es, en in lesson[\'circuits\']]}\\n    def settle(self):\\n        \\"\\"\\"Tutorial measurements are sampled at once with local Qiskit, never sent to IonQ.\\"\\"\\"\\n        while self.game.phase == \'measure\':\\n            sampler = LocalSampler()\\n            self.game.complete_measure([sampler.sample(gates) for gates in self.sequences()])\\n    def advance(self):\\n        \\"\\"\\"Move past the current step and play Bot Q\'s scripted moves.\\"\\"\\"\\n        self.settle()\\n        self.coach += 1\\n        while self.coach < len(tutorial.STEPS) and \'bot\' in tutorial.STEPS[self.coach]:\\n            action, value = tutorial.STEPS[self.coach][\'bot\']\\n            if self.game.actor != 1: raise RuntimeError(\'Guion del tutorial desincronizado\')\\n            self.game.dispatch(action, value)\\n            self.settle()\\n            self.coach += 1\\n    def coach_feedback(self, ok, text):\\n        \\"\\"\\"Bot Q\'s answer to a challenge or a quiz, shown in its panel until the next move.\\"\\"\\"\\n        self.feedback = {\'ok\':ok, \'text\':text[0], \'text_en\':text[1]} if text else None\\n    def tutorial_action(self, action, value):\\n        step = tutorial.STEPS[self.coach]\\n        self.feedback = None\\n        if action == \'coach_next\':\\n            if \'quiz\' in step:\\n                # A wrong answer keeps the question open and gives a hint.\\n                if value != step[\'quiz\'][\'answer\']: return self.coach_feedback(False, step[\'hint\'])\\n                self.coach_feedback(True, step.get(\'ok\'))\\n            elif step.get(\'expect\') or step.get(\'final\'): raise ValueError(\'Segu\\u00ed la indicaci\\u00f3n de Bot Q para continuar.\')\\n            self.advance()\\n            return\\n        if step.get(\'expect\') != [action, value]:\\n            if step.get(\'challenge\') and action in self.game.legal():\\n                # In a challenge every legal move may be tried; a wrong one is not played.\\n                hints = step.get(\'hints\', {})\\n                return self.coach_feedback(False, hints.get(f\'{action}:{value}\') or hints.get(action) or step[\'hint\'])\\n            title = step.get(\'title_en\', step[\'title\']) if self.lang == \'en\' else step[\'title\']\\n            raise ValueError(\'En el tutorial, segu\\u00ed la indicaci\\u00f3n de Bot Q: \' + title + \'.\')\\n        self.game.dispatch(action, value)\\n        self.coach_feedback(True, step.get(\'ok\'))\\n        self.advance()\\n    def action(self, payload):\\n        self.error = None\\n        action = payload[\'action\']; value = payload.get(\'value\')\\n        if payload.get(\'lang\') in (\'es\', \'en\'): self.lang = payload[\'lang\']\\n        if action in (\'new\',\'tutorial\') and self.needs_measurement():\\n            raise ValueError(\'Hay una medici\\u00f3n pendiente. Completala o consult\\u00e1 su resultado antes de cambiar de partida o lecci\\u00f3n.\')\\n        if action == \'dev_mode\':\\n            if type(value) is not bool: raise ValueError(\'Modo inv\\u00e1lido\')\\n            if self.host_local and not value: raise ValueError(\'El servidor local solo admite modo de desarrollo\')\\n            if value != self.local and self.remote and self.remote.started is not None:\\n                raise ValueError(\'Consult\\u00e1 el resultado IonQ pendiente antes de cambiar el modo de medici\\u00f3n.\')\\n            self.local = value\\n        elif action == \'new\':\\n            if isinstance(value, dict):\\n                game = Game(value.get(\'names\'), privacy=value.get(\'privacy\', False), difficulty=value.get(\'difficulty\', \'normal\'))\\n            else: game = Game(value)\\n            self.guided = False\\n            self.game = game\\n        elif action == \'tutorial\':\\n            # Classic Truco against scripted Bot Q; the quantum card is not used yet.\\n            self.game = Game(list(tutorial.NAMES[self.lang]), quantum=False, deals=tutorial.DEALS, mano=tutorial.MANO)\\n            self.guided = True\\n            self.coach = -1\\n            self.feedback = None\\n            self.advance()\\n        elif action == \'lesson\':\\n            if value is not None and (type(value) is not int or not 0 <= value < len(tutorial.GATE_LESSONS)):\\n                raise ValueError(\'Lecci\\u00f3n inv\\u00e1lida\')\\n            self.lesson = value\\n        elif action == \'reveal\': return self.output(private=True)\\n        elif action == \'public\': return self.output()\\n        else:\\n            if self.game is None: raise ValueError(\'Inici\\u00e1 una partida\')\\n            if self.guided: self.tutorial_action(action, value)\\n            else: self.game.dispatch(action,value)\\n        return self.output(private=action in (\'choose\',\'edit\'))\\n    def needs_measurement(self):\\n        return self.game is not None and self.game.phase==\'measure\'\\n    def sequences(self):\\n        return [self.game.q[p].gates for p in self.game.measure_requests]\\n    def accept_measurements(self, measurements):\\n        self.game.complete_measure(measurements)\\n    def start(self, backend=None):\\n        if not self.needs_measurement(): return self.output()\\n        if self.local:\\n            sampler = LocalSampler()\\n            self.accept_measurements([sampler.sample(gates) for gates in self.sequences()])\\n            return self.output()\\n        if self.remote is None: self.remote = RemoteMeasurement(backend)\\n        self.remote.start(self.sequences())\\n        return self.output()\\n    def poll(self):\\n        if self.local: return {\'done\':True,\'view\':self.output()}\\n        response = self.remote.poll()\\n        if response[\'done\']:\\n            self.accept_measurements(response[\'measurements\'])\\n            self.remote.release()\\n        return {\'done\':response[\'done\'],\'view\':self.output()}\\n    def safe(self, fn):\\n        self.error = None\\n        try: return fn()\\n        except (ValueError,RuntimeError,TimeoutError) as exc:\\n            self.error = error_text(str(exc), self.lang)\\n            self.errors.append({\'type\':type(exc).__name__,\'message\':self.error})\\n            return self.output()\\n        except Exception as exc:\\n            # Do not return arbitrary provider errors which can contain credentials.\\n            self.error = error_text(f\'Fall\\u00f3 la operaci\\u00f3n ({type(exc).__name__}). No se gener\\u00f3 un resultado.\', self.lang)\\n            self.errors.append({\'type\':type(exc).__name__})\\n            return self.output()\\n\\n# In Qollab the Python module is imported once per run; all state stays in memory.\\n_session = Session()\\n\\ndef dispatch_json(payload):\\n    return json.dumps(_session.safe(lambda:_session.action(json.loads(payload))))\\n\\ndef start_json(backend):\\n    return json.dumps(_session.safe(lambda:_session.start(backend)))\\n\\ndef poll_json():\\n    return json.dumps(_session.safe(_session.poll))\\n\\n\\ndef demo_json():\\n    import base64\\n    # Source checkouts keep artifacts/; Qollab\'s flat upload keeps root files.\\n    for prefix in (\'artifacts/\', \'\'):\\n        try:\\n            with open(prefix + \'truco-cuantico-demo.mp4\', \'rb\') as f:\\n                data = base64.b64encode(f.read()).decode(\'ascii\')\\n            with open(prefix + \'DEMO_TRANSCRIPT.txt\', encoding=\'utf8\') as f:\\n                transcript = f.read()\\n            return json.dumps({\'data\':data,\'transcript\':transcript})\\n        except OSError:\\n            continue\\n    return json.dumps({\'error\':\'Video no disponible en este paquete. Consult\\u00e1 DEMO_SCRIPT.md.\'})\\n"}')
_SERVICE = None


def _service():
    global _SERVICE
    if _SERVICE is None:
        root = '_qriollo_qollab'
        package = types.ModuleType(root)
        package.__path__ = []
        package.__package__ = root
        sys.modules[root] = package
        exec(compile(_SOURCES['__init__'], '<qollab_engine/__init__.py>', 'exec'), package.__dict__)
        for name in ('i18n', 'gates', 'classic', 'quantum', 'remote', 'game', 'tutorial', 'service'):
            module = types.ModuleType(root + '.' + name)
            module.__package__ = root
            module.__file__ = '<qollab_engine/' + name + '.py>'
            sys.modules[module.__name__] = module
            setattr(package, name, module)
            exec(compile(_SOURCES[name], module.__file__, 'exec'), module.__dict__)
        _SERVICE = sys.modules[root + '.service']
    return _SERVICE


def dispatch_json(payload):
    return _service().dispatch_json(payload)


def start_json(backend):
    return _service().start_json(backend)


def poll_json():
    return _service().poll_json()


def demo_json():
    return _service().demo_json()
